window.LAV_PRODUCTS = [{"id":1,"title":"Amouage Guidance Eau de Parfum","tagline":"Цветочный · фруктовый · древесно-амбровый · 2023","description":"Guidance — это какое-то невероятно красивое парфюмерное излишество. Густой, сливочный, томный, обволакивающий. В нём столько чувственности, что хочется рассматривать каждую ноту отдельно.\n\nПредставьте спелую, сочную грушу, которую подали с нежнейшим ореховым кремом. Рядом — огромный букет бархатистых роз, немного шафрана и тёплая древесина. Всё это словно окутано тончайшей восточной вуалью.\n\nСначала Guidance кажется почти гурманским, но постепенно фруктовая сладость уступает место роскошному цветочно-древесному звучанию. Появляется сандаловая мягкость, смолистая глубина, лёгкая пряность. Аромат становится плотнее, теплее, приобретает особенную, почти телесную притягательность.\n\nВ нём есть настроение дорогих интерьеров, шёлковых тканей, приглушённого света и долгих объятий. Это не история про скромность и минимализм. Guidance любит внимание, красивые жесты и удовольствие от жизни.\n\nЕго оценят те, кто любит насыщенные, сладковато-древесные ароматы, роскошные цветочные композиции и выразительный шлейф.","notes":{"top":"Груша, ладан, фундук.","middle":"Османтус, роза, шафран, жасмин самбак.","base":"Сандал, ваниль, акигалавуд, амбра (ambergris), лабданум.","other":""},"brand":"Amouage","name":"Guidance EDP","price3":1500,"price5":2500,"price10":5000,"priceFull":null,"available":true,"hit":true,"new":false,"image":"assets/products/001.webp","placeholder":false},{"id":2,"title":"Attar Collection Musk Kashmir Eau de Parfum","tagline":"Мускусный · пудровый · древесный","description":"Musk Kashmir — аромат, в котором хочется буквально утонуть. Мягкий, пушистый, бархатный, словно тончайший кашемир, согретый теплом кожи. Его прелесть не в громких эффектах, а в удивительной тактильности.\n\nПредставьте светлый свитер, чистые простыни, тёплые ладони и лёгкую пряность в воздухе. Белый мускус создаёт ощущение нежной пудровой дымки, а сандал добавляет сливочную, древесную глубину. Белые цветы здесь не превращаются в пышный букет — они лишь делают звучание мягче.\n\nЭто очень личная парфюмерная история. Спокойная, уютная, но при этом чувственная: хочется снова поднести запястье к носу и поймать этот едва уловимый эффект чистой, ухоженной кожи.\n\nMusk Kashmir понравится тем, кто любит деликатные мускусы, пудровые оттенки и ароматы, которые не надоедают даже при близком знакомстве.","notes":{"top":"Белый перец, гвоздика.","middle":"Гардения, белые цветы.","base":"Сандал, белый мускус.","other":""},"brand":"Attar Collection","name":"Musk Kashmir EDP","price3":750,"price5":1250,"price10":2500,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/002.webp","placeholder":false},{"id":3,"title":"Carolina Herrera Cedar Chic Eau de Parfum","tagline":"Древесный · альдегидный · цветочный","description":"Cedar Chic — аромат идеально выглаженной белой рубашки, дорогого мыла и безупречного вкуса. Свежий, суховатый, светлый, собранный — и при этом совсем не холодный.\n\nВ самом начале альдегиды дают искрящуюся, почти хрустальную чистоту. Бергамот добавляет прохлады, цветок апельсина — тонкую цветочную нежность. А затем появляется кедр: гладкий, благородный, с красивой древесной строгостью. Белый мускус смягчает композицию, оставляя ощущение свежей ткани на коже.\n\nВ нём легко представить утро в красивом отеле: большие окна, белоснежное бельё, кофе на столике и ощущение, что никуда не нужно спешить. Это роскошь деталей, а не украшений.\n\nЕго особенно оценят поклонники чистых, интеллигентных, несладких ароматов, которые умеют быть заметными благодаря качеству самого звучания.","notes":{"top":"Альдегиды, бергамот.","middle":"Цветок апельсина.","base":"Кедр, белый мускус.","other":""},"brand":"Carolina Herrera","name":"Cedar Chic EDP","price3":2400,"price5":4000,"price10":8000,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/003.webp","placeholder":false},{"id":4,"title":"Chanel Bleu de Chanel Eau de Parfum","tagline":"Древесный · ароматический · цитрусовый","description":"Bleu de Chanel — тот самый случай, когда безупречный вкус ощущается с первых секунд. Свежий, благородный, собранный, с красивой древесной глубиной и спокойной уверенностью.\n\nВ начале — прохладная цитрусовая искристость и ароматические оттенки. Затем свежесть становится мягче, появляются сухая древесина, тёплые пряные нюансы и узнаваемая гладкость сандала. В базе ощущаются древесные и амбровые тона, которые делают аромат особенно притягательным.\n\nОн напоминает идеально сидящий пиджак, часы без лишнего блеска и человека, который умеет держать слово. Уместен и днём, и вечером: с ним не нужно подбирать особый повод.\n\nBleu de Chanel понравится тем, кто выбирает свежую древесную классику, аккуратный шлейф и элегантность без показной эффектности.","notes":{"top":"Грейпфрут, лимон, бергамот, мята, розовый перец, альдегиды, кориандр.","middle":"Имбирь, жасмин, мускатный орех, дыня.","base":"Ладан, амбра, кедр, сандал, пачули, лабданум, амбровая древесина.","other":"Цитрусовый аккорд, ароматические и древесные оттенки, сандал, кедр, лабданум."},"brand":"Chanel","name":"Bleu de Chanel EDP","price3":825,"price5":1375,"price10":2750,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/004.webp","placeholder":false},{"id":5,"title":"Chloé Atelier des Fleurs Cedrus Eau de Parfum","tagline":"Древесный · мягкий · мускусный","description":"Cedrus — аромат светлого дерева, льняных тканей и тихого утра, в котором всё удивительно красиво. Воздушный, суховатый, нежный, с природной элегантностью и очень деликатным теплом.\n\nПоначалу ощущается лёгкая пряность кардамона, затем раскрывается спокойная древесная композиция: мягкий сандал, сухой ветивер, оттенки кедра. В звучании есть ощущение чистоты и лёгкой кремовости, будто тёплое дерево отполировали до шелковистой гладкости.\n\nПредставьте дом с большими окнами, деревянной мебелью, свежими цветами на столе и открытой книгой. Ничего лишнего — только фактуры, воздух и удовольствие от простых вещей.\n\nCedrus понравится тем, кто любит сдержанную древесную парфюмерию, спокойные композиции и ощущение естественной ухоженности.","notes":{"top":"Кардамон.","middle":"Ветивер, сандал.","base":"Древесные аккорды, дубовый мох.","other":""},"brand":"Chloé Atelier des Fleurs","name":"Cedrus EDP","price3":825,"price5":1375,"price10":2750,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/005.webp","placeholder":false,"photo_reference_source":"https://www.sephora.fr/on/demandware.static/-/Sites-masterCatalog_Sephora/default/dwc93ad94a/images/hi-res/SKU/SKU_2248/519488_swatch.jpg"},{"id":6,"title":"Clive Christian Noble XXI Art Deco Blonde Amber","tagline":"Амбровый · пряный · табачный","description":"Blonde Amber — роскошь, у которой совершенно нет желания быть скромной. Густой, пряный, бархатный, с тёплой сладостью и красивой табачной дымкой. Кажется, будто в одном флаконе собрали всё самое соблазнительное из эпохи ар-деко.\n\nПредставьте тяжёлые портьеры, хрустальные бокалы, золотистый свет и десерт с сухофруктами, к которому подали выдержанный ром. Горький апельсин добавляет искру, пряности — темперамент, а белый табак раскрывается мягко, с медово-дымным оттенком. В сердце — пышные цветы, шафран и тёплая древесина.\n\nПостепенно аромат становится ещё глубже: ваниль, смолы и бобы тонка превращают его в почти осязаемое удовольствие. Не конфетная сладость, а богатая, взрослая, многослойная гурманика.\n\nBlonde Amber понравится тем, кто любит сложные восточные композиции, тёплый табак, густую амбру и ароматы, которые хочется разгадывать весь вечер.","notes":{"top":"Горький апельсин, имбирь, кардамон, розовый перец, ладан, ром, бергамот, грейпфрут.","middle":"Белый табак, сухофрукты, тубероза, сандал, жасмин, ирис, шафран, османтус.","base":"Бобы тонка, лабданум, мирра, пачули, мускус, ветивер, кедр, ваниль.","other":""},"brand":"Clive Christian","name":"Noble XXI Art Deco Blonde Amber","price3":2850,"price5":4750,"price10":9500,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/006.webp","placeholder":false},{"id":7,"title":"Creed Aventus Eau de Parfum","tagline":"Фруктовый · древесный · шипровый","description":"Aventus — аромат с характером победителя, но без дешёвой бравады. Сочный, энергичный, чуть дымный, с тем самым сочетанием свежести и древесной силы, которое невозможно спутать с обычным цитрусовым парфюмом.\n\nВ начале — спелый ананас, хрустящее яблоко, чёрная смородина и бергамот. Фруктовая яркость быстро встречается с берёзовыми и хвойными оттенками, жасмином и прохладной древесной глубиной. В шлейфе — мох, амбровые нюансы и мягкая ваниль.\n\nПредставьте ранний вылет бизнес-классом, уверенное рукопожатие, идеально сидящий пиджак и привычку не откладывать жизнь на потом. В нём есть движение, собранность и немного авантюризма.\n\nAventus особенно понравится тем, кто любит свежие, но не простые ароматы: фруктовую сочность с благородным древесным продолжением.","notes":{"top":"Яблоко, чёрная смородина, ананас, итальянский бергамот.","middle":"Жасмин, берёза, ягоды можжевельника.","base":"Дубовый мох, ваниль, амбра (ambergris).","other":""},"brand":"Creed","name":"Aventus EDP","price3":1200,"price5":2000,"price10":4000,"priceFull":null,"available":true,"hit":true,"new":false,"image":"assets/products/007.webp","placeholder":false},{"id":8,"title":"Ex Nihilo Blue Talisman Extrait de Parfum","tagline":"Фруктовый · цветочный · древесно-амбровый","description":"Blue Talisman Extrait — будто драгоценный камень, который на свету каждый раз раскрывает новый оттенок. Сначала прозрачный, искристый, прохладный. А через несколько минут — удивительно гладкий, тёплый и чувственный.\n\nСочная груша и бергамот создают светлое фруктовое начало. Потом раскрываются жасмин и цветок апельсина: мягкие, солнечные, словно нагретые полуденным светом. В базе сандал, ваниль, мускус и амбровая древесина придают аромату кремовую глубину.\n\nВ нём легко представить белый камень, лазурную воду, лёгкую одежду и вечер, который не хочется заканчивать. Свежесть здесь не исчезает — она постепенно обрастает теплом и красивой древесной фактурой.\n\nBlue Talisman Extrait оценят те, кто любит фруктовую чистоту, но ждёт от аромата объёма, мягкой сладости и насыщенного послевкусия.","notes":{"top":"Груша, бергамот.","middle":"Цветок апельсина, жасмин.","base":"Сандал, ваниль, мускусы, Ambrofix™, амбровая древесина.","other":""},"brand":"Ex Nihilo","name":"Blue Talisman","price3":1380,"price5":2300,"price10":4600,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/008.webp","placeholder":false},{"id":9,"title":"Ex Nihilo Lust in Paradise Extrait de Parfum","tagline":"Фруктовый · цветочный · древесно-амбровый","description":"Lust in Paradise Extrait — французская Ривьера на закате, когда жара уже спала, а воздух всё ещё хранит тепло дня. Роскошный, пряный, цветочный, с сочной ягодной кислинкой и мягким, соблазнительным шлейфом.\n\nЧёрная смородина звучит ярко и чуть терпко, розовый перец и красный имбирь добавляют искру. Затем распускаются роза и жасмин самбак — пышные, бархатистые, но без тяжёлой цветочной пудры. Древесно-амбровая база и мускусы делают композицию тёплой и обволакивающей.\n\nПредставьте вечернюю прогулку по набережной, кожу после солнца, шелест лёгкой ткани и аромат цветов из сада за каменной оградой. Здесь есть и беззаботность отпуска, и предвкушение красивой встречи.\n\nЕго оценят любители насыщенных фруктово-цветочных ароматов, где нежность соседствует с пряностью и древесной чувственностью.","notes":{"top":"Чёрная смородина, розовый перец, Rosyfolia™, красный имбирь.","middle":"Petalia™, абсолют розы, жасмин самбак.","base":"Akigalawood™, кедр, Ambrofix™, мускусы.","other":""},"brand":"Ex Nihilo","name":"Lust in Paradise","price3":1350,"price5":2250,"price10":4500,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/009.webp","placeholder":false},{"id":10,"title":"Hormone Paris This Is Not GABA Parfum","tagline":"Свежий · фруктово-цветочный · амбровый","description":"This Is Not GABA — аромат того редкого момента, когда наконец можно никуда не торопиться. Светлый, сочный, воздушный, с мягкими цветами и спокойным тёплым послевкусием.\n\nСначала — спелая маракуйя и свежий мандарин, словно первый глоток прохладного напитка на солнечной террасе. Затем появляются фрезия, жасмин и ландыш: нежные, прозрачные, без приторной сладости. Мшистые и амбровые оттенки придают этой лёгкости уютную глубину.\n\nОн напоминает утро без будильника, открытое окно, чистую постель и целый день впереди, который можно провести как угодно. В нём много воздуха, света и приятной внутренней тишины.\n\nThis Is Not GABA понравится тем, кто выбирает свежие фруктово-цветочные композиции и любит, когда аромат оставляет ощущение лёгкости, а не тяжёлой сладости.","notes":{"top":"Маракуйя, мандарин.","middle":"Фрезия, жасмин, ландыш.","base":"Мшистые ноты, амбровые ноты.","other":""},"brand":"Hormone Paris","name":"This Is Not GABA","price3":750,"price5":1250,"price10":2500,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/010.webp","placeholder":false},{"id":11,"title":"Maison Francis Kurkdjian 724 Eau de Parfum","tagline":"Альдегидный · цветочный · мускусный","description":"724 — это запах большого города, в котором вдруг стало удивительно легко дышать. Звонкий, светлый, чистый, с нежной цветочной дымкой и мягким, почти сливочным послевкусием.\n\nПредставьте утро в красивом отеле: за окном просыпается город, на кровати лежит белоснежная рубашка, а из открытого окна тянет свежим воздухом. Альдегиды и бергамот создают искрящуюся прохладу, будто солнечный свет отражается от стеклянных фасадов. Затем раскрываются жасмин, душистый горошек и чубушник — воздушные, нежные, без тяжёлой цветочной сладости.\n\nПостепенно сандал и белый мускус делают аромат более тёплым и тактильным. Это уже не просто чистота, а ощущение идеально ухоженной кожи и дорогой ткани, к которой приятно прикоснуться.\n\n724 понравится тем, кто любит прозрачные цветочные композиции, свежесть после душа и элегантность, в которой каждая деталь на своём месте.","notes":{"top":"Альдегиды, бергамот.","middle":"Жасмин грандифлорум, душистый горошек, чубушник.","base":"Сандал, белый мускус.","other":""},"brand":"Maison Francis Kurkdjian","name":"724 EDP","price3":1500,"price5":2500,"price10":5000,"priceFull":null,"available":true,"hit":true,"new":false,"image":"assets/products/011.webp","placeholder":false},{"id":12,"title":"Parfums de Marly Althaïr Eau de Parfum","tagline":"Ванильный · пряный · древесный","description":"Althaïr — ваниль, которой явно тесно в кондитерской. Густая, золотистая, пряная, с роскошной кремовой текстурой и таким тёплым характером, что хочется закутаться в неё целиком.\n\nСначала бергамот и мандарин дают свежую искру, а элеми добавляет смолистую остроту. Затем появляется корица, кардамон и цветок апельсина — словно ароматный воздух в красивом восточном доме, где на столе стоят пряности и ещё тёплый десерт.\n\nВ базе раскрывается бурбонская ваниль: нежная, насыщенная, обволакивающая. Пралине делает её аппетитнее, а гваяковое дерево добавляет сухую благородную глубину. Сладость здесь не детская и не плоская — она сложная, уютная и очень соблазнительная.\n\nAlthaïr понравится тем, кто любит ваниль с характером, пряные гурманские ароматы и ощущение тёплого кашемира в прохладный вечер.","notes":{"top":"Бергамот, мандарин, элеми.","middle":"Цветок апельсина, корица, кардамон.","base":"Бурбонская ваниль, гваяковое дерево, пралине.","other":""},"brand":"Parfums de Marly","name":"Althaïr EDP","price3":960,"price5":1600,"price10":3200,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/012.webp","placeholder":false},{"id":13,"title":"Parfums de Marly Athénaïs Eau de Parfum","tagline":"Цветочный · цитрусовый · амбровый","description":"Athénaïs — аромат красивой, уверенной женственности: сияющий, нарядный, чуть кокетливый, но с удивительно благородной мягкостью. В нём чувствуется радость от того, что можно быть разной — нежной, смелой, лёгкой, непредсказуемой.\n\nПервые секунды напоминают солнечный сад с цитрусовыми деревьями. Юзу и бергамот искрятся свежестью, нероли придаёт композиции изящную горчинку. Потом распускаются цветок апельсина и жасмин — нежные, светлые, будто лепестки, нагретые солнцем.\n\nБлиже к коже появляется совсем другое настроение: бобы тонка, ваниль и амброкс делают цветочную свежесть тёплой, пудровой и чувственной. Словно лёгкое шёлковое платье сменилось мягкой вечерней накидкой.\n\nAthénaïs понравится тем, кто любит сияющие белоцветочные ароматы с цитрусовым началом и нежной, притягательной сладостью в финале.","notes":{"top":"Нероли, бергамот, юзу.","middle":"Цветок апельсина, жасмин.","base":"Бобы тонка, ваниль, амброкс.","other":""},"brand":"Parfums de Marly","name":"Athénaïs EDP","price3":1350,"price5":2250,"price10":4500,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/013.webp","placeholder":false},{"id":14,"title":"Xerjoff Torino21 Eau de Parfum","tagline":"Цитрусовый · зелёный · ароматический","description":"Torino21 — настоящий глоток ледяной свежести. Звонкий, зелёный, искристый, с сочными цитрусами и прохладой свежесорванных трав. Кажется, будто кто-то открыл окно в разгар жаркого дня и впустил целый сад.\n\nЛимон, мята, базилик и тимьян создают энергичное начало — почти как лимонад со льдом, который подали на залитой солнцем террасе. Затем появляется лаванда, розмарин, жасмин и лёгкая терпкость чёрной смородины. Аромат становится объёмнее, но не теряет своей прозрачной прохлады.\n\nМускус и вербена оставляют чистое, тонкое древесно-травянистое послевкусие. В нём есть спортивный азарт, ощущение свободы и желание немедленно куда-нибудь отправиться.\n\nTorino21 понравится тем, кто ищет свежесть без банального «запаха геля для душа», любит зелёные травы, цитрусы и энергичные композиции.","notes":{"top":"Базилик, лимон, мята, тимьян.","middle":"Чёрная смородина, жасмин, лаванда, розмарин.","base":"Мускус, вербена.","other":""},"brand":"Xerjoff","name":"Torino21 EDP","price3":900,"price5":1500,"price10":3000,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/014.webp","placeholder":false},{"id":15,"title":"Louis Vuitton Imagination Eau de Parfum","tagline":"Цитрусовый · чайный · амбровый","description":"Imagination — аромат свободы, путешествий и той особенной свежести, которая пахнет очень дорого. Чистый, искристый, интеллигентный, с прозрачной чайной терпкостью и тёплой амбровой глубиной.\n\nПредставьте раннее утро в незнакомом городе: на столе чашка крепкого чёрного чая, за окном солнечный свет, а впереди целый день без заранее написанного сценария. Бергамот и цитрусовые оттенки освежают, имбирь добавляет пикантную искру, нероли — светлую цветочную грань.\n\nЧёрный чай делает аромат особенно интересным: чуть терпким, суховатым, спокойным. А амброкс придаёт ему современную, гладкую, почти минеральную глубину. Свежесть остаётся, но постепенно становится более тёплой и притягательной.\n\nImagination понравится тем, кто любит благородные цитрусовые ароматы, чайные оттенки и ощущение безупречной свежести без тяжёлой сладости.","notes":{"top":"Цитрон, калабрийский бергамот, сицилийский апельсин.","middle":"Тунисский нероли, нигерийский имбирь, цейлонская корица.","base":"Китайский чёрный чай, амброксан, гваяковое дерево, ладан.","other":"Амброкс, чёрный чай из Китая, тунисский нероли, сицилийский цедрат, калабрийский бергамот, нигерийский имбирь, цейлонская корица."},"brand":"Louis Vuitton","name":"Imagination EDP","price3":1800,"price5":3000,"price10":6000,"priceFull":null,"available":true,"hit":true,"new":false,"image":"assets/products/015.webp","placeholder":false},{"id":16,"title":"Amouage Existence Eau de Parfum","tagline":"Цветочный · мускусный · смолистый","description":"Existence — аромат почти невесомой красоты, в которой неожиданно обнаруживается огромная глубина. Светлый, прохладный, прозрачный, будто утренний воздух после дождя. Но за этой хрупкостью скрывается удивительная сила.\n\nПредставьте сад на рассвете: ещё прохладные лепестки ландыша, нежная роза и свет, который только начинает пробиваться сквозь туман. Затем в эту цветочную прозрачность вплетается ладан — не тяжёлый и церковный, а воздушный, смолистый, почти медитативный. Лабданум добавляет теплоты и мягкой золотистой глубины.\n\nПостепенно белый мускус, бензоин и амбровые оттенки делают композицию более округлой, почти тактильной. В нём есть редкое ощущение тишины, которую не хочется нарушать.\n\nExistence понравится тем, кто любит необычные цветочные ароматы, чистые мускусы и тонкую смолистую дымку вместо привычной сладости.","notes":{"top":"Ландыш, роза.","middle":"Ладан, Mystikal, лабданум.","base":"Амбра (ambergris), белый мускус, бензоин.","other":""},"brand":"Amouage","name":"Existence EDP","price3":1410,"price5":2350,"price10":4700,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/016.webp","placeholder":false},{"id":17,"title":"Bvlgari Le Gemme Tygar Eau de Parfum","tagline":"Цитрусовый · древесно-амбровый","description":"Tygar — грейпфрут, который словно пропустили через драгоценный камень. Сочный, искристый, терпкий, с невероятно гладкой и мощной амбровой глубиной. Здесь свежесть совсем не легкомысленная — у неё сильный характер.\n\nПредставьте разрезанный спелый грейпфрут: холодные брызги сока, горчинка цедры, яркий цитрусовый аромат. И вдруг на смену этой сочности приходит тёплая, минеральная, почти вибрирующая амбровая древесность. Контраст прохлады и тепла делает Tygar особенно узнаваемым.\n\nВ нём есть энергия большого города, нагретого солнцем камня и свежего ветра с моря. Он ощущается одновременно собранным и свободным, чистым и чувственным.\n\nTygar понравится тем, кто любит яркие цитрусы, но хочет, чтобы свежесть имела плотность, глубину и выразительный характер.","notes":{"top":"Грейпфрут.","middle":"Имбирь, амбретта.","base":"Амброксан, мускус, ветивер, пачули.","other":"Грейпфрутовый аккорд, амбровый аккорд (ambergris). Bvlgari не публикует для Tygar полную трёхступенчатую пирамиду."},"brand":"Bvlgari","name":"Le Gemme Tygar EDP","price3":1350,"price5":2250,"price10":4500,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/017.webp","placeholder":false},{"id":19,"title":"Chopard Vétiver d’Haïti au Thé Vert Eau de Parfum","tagline":"Зелёный · чайный · древесный","description":"Vétiver d’Haïti au Thé Vert — аромат с красивой, почти аристократической сдержанностью. Травянистый, древесный, суховатый, с мягким теплом зелёного чая и ощущением идеально чистого воздуха.\n\nПредставьте террасу загородного дома после дождя. На столе — чашка свежезаваренного зелёного чая, вокруг влажная зелень, деревянные перила и прохладный ветер. Чайные оттенки здесь не сладкие: они прозрачные, чуть терпкие, с приятной растительной горчинкой.\n\nПостепенно вступает ветивер — землистый, благородный, с тонкой дымной сухостью. Кедр добавляет структуру, а мускус и древесные молекулы оставляют спокойное, тёплое послевкусие.\n\nЭтот аромат понравится тем, кто ценит зелёные, интеллигентные композиции, чайную свежесть и древесину без тяжёлой сладости.","notes":{"top":"Зелёный чай, растительная амбра.","middle":"Гаитянский ветивер, кедр.","base":"Wolfwood, мускус.","other":""},"brand":"Chopard","name":"Vétiver d’Haïti au Thé Vert EDP","price3":900,"price5":1500,"price10":3000,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/019.webp","placeholder":false},{"id":20,"title":"Ella K Musc K Eau de Parfum","tagline":"Мускусный · минеральный · древесный","description":"Musc K — будто белый песок, солёный ветер и кожа после долгого дня у воды. Чистый, воздушный, прохладный, с нежной пудровостью и необычной минеральной глубиной. В нём есть свобода, которую невозможно изобразить красивой одеждой.\n\nПредставьте бесконечные светлые дюны и прозрачные лагуны. Морской ветер приносит солоноватую свежесть, песчаная лилия добавляет нежный цветочный оттенок, а перец — тонкую искру. Ирис делает аромат гладким и слегка пудровым, словно сухой шёлк.\n\nДальше появляются ветивер, древесные оттенки и белый мускус. Всё звучит спокойно, почти невесомо, но удивительно притягательно. Не запах моря в привычном понимании, а ощущение пространства, света и чистой кожи.\n\nMusc K понравится тем, кто любит необычные мускусы, солоноватые минеральные аккорды и свежесть с мягкой древесной основой.","notes":{"top":"Песчаная лилия, розовый перец.","middle":"Кедр, корень ириса.","base":"Мускус, гаитянский ветивер, Ambrofix.","other":"Розовый перец, песчаная лилия, ирис, кедр, гаитянский ветивер, мускус. В описании бренда также упомянуты солоноватые древесные оттенки и Ambrofix. Бренд приводит перечень нот без точного деления на три уровня."},"brand":"Ella K","name":"Musc K EDP","price3":900,"price5":1500,"price10":3000,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/020.webp","placeholder":false},{"id":21,"title":"Escentric Molecules Escentric 02","tagline":"Свежий · минеральный · мускусно-древесный","description":"Escentric 02 — свежесть с неожиданно чувственным характером. Прозрачный, искристый, чуть солоноватый, словно воздух у моря, который успел нагреться на солнце.\n\nСначала ощущаются сочные цитрусы, можжевельник и прохладная травянистость. Затем появляется тонкая цветочная дымка, имбирная пряность и почти невесомый ирис. Но главная магия здесь — амброксан: он придаёт аромату минеральную гладкость, тёплую телесность и особенное ощущение чистоты.\n\nПредставьте солнечный день, белую хлопковую рубашку и ветер, который приносит запах моря. В этом аромате нет тяжёлой сладости — только воздух, кожа и тонкое притяжение.\n\nЕго оценят те, кто любит необычную свежесть, мускусные оттенки и парфюмерию, которая раскрывается постепенно, а не рассказывает о себе всё с первой секунды.","notes":{"top":"Almdudler (травяной лимонад), ягоды можжевельника, мандарин, лайм, бергамот.","middle":"Имбирь, фрезия, шалфей мускатный, розовый перец, гедион, ирис.","base":"Мускон, амброксан, ветивер, бобы тонка.","other":""},"brand":"Escentric Molecules","name":"Escentric 02","price3":450,"price5":750,"price10":1500,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/021.webp","placeholder":false},{"id":22,"title":"Escentric Molecules Molecule 01 + Mandarin","tagline":"Цитрусовый · древесный · свежий","description":"Molecule 01 + Mandarin — это счастье в виде мандариновой кожуры. Яркий, сочный, искристый аромат, в котором свежесть цитруса встречается с мягким древесным теплом.\n\nВ первые мгновения — настоящий взрыв мандарина: будто только что очистили спелый плод и ароматное масло осталось на пальцах. Затем фруктовая яркость постепенно стихает, уступая место Iso E Super — прозрачному, бархатистому древесному звучанию.\n\nПредставьте солнечный свет на светлом дереве, открытую террасу и лёгкую одежду после душа. Всё очень просто, но именно в этой простоте есть особенное удовольствие.\n\nПонравится тем, кто любит натурально звучащие цитрусы, ненавязчивую древесину и ароматы без тяжёлой сладости.","notes":{"top":"Мандарин.","middle":"Мандарин и Iso E Super (сочетание двух заявленных компонентов).","base":"Iso E Super (древесная основа, без дополнительных нот).","other":"Мандарин, Iso E Super. Бренд не заявляет дополнительных нот и не делит композицию на три ступени."},"brand":"Escentric Molecules","name":"Molecule 01 + Mandarin","price3":480,"price5":800,"price10":1600,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/022.webp","placeholder":false},{"id":23,"title":"Essential Parfums Bois Impérial Eau de Parfum","tagline":"Древесный · пряный · зелёный","description":"Bois Impérial — древесина с электрическим характером. Свежий, острый, пряный, суховатый, с удивительно красивым контрастом зелёных трав и тёплых древесных оттенков.\n\nПредставьте, как растирают между пальцами листья тайского базилика: сочная зелень, пряная горчинка, лёгкая перечная искра. Затем раскрываются ветивер и мощные древесные аккорды. Akigalawood добавляет необычную сухую, чуть землистую фактуру, а амбровые молекулы делают композицию гладкой и стойкой по характеру звучания.\n\nВ нём есть эстетика современного города: бетон, стекло, натуральное дерево, свежий воздух после дождя. Никакой кондитерской сладости — только чистая энергия, архитектурная чёткость и характер.\n\nBois Impérial понравится любителям выразительных древесных ароматов, пряной зелени и необычной современной парфюмерии.","notes":{"top":"Тайский базилик, грейпфрутовые оттенки, перец тимут.","middle":"Гаитянский ветивер, Georgywood, Petalia.","base":"Akigalawood, пачули, Ambrofix.","other":""},"brand":"Essential Parfums","name":"Bois Impérial EDP","price3":780,"price5":1300,"price10":2600,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/023.webp","placeholder":false},{"id":24,"title":"Goldfield & Banks Pacific Rock Moss Eau de Parfum","tagline":"Акватический · ароматический · свежий","description":"Pacific Rock Moss — запах отпуска, в котором главное удовольствие — ничего не планировать. Прохладный, солоноватый по настроению, зелёный, прозрачный, будто утренний воздух над океаном.\n\nЛимон добавляет бодрящую свежесть, прибрежный мох — влажную зелёную глубину. Шалфей и герань придают аромату тонкую травянистую терпкость, а кедр и белый мускус оставляют мягкий, чистый древесный след.\n\nПредставьте австралийское побережье: нагретые солнцем камни, океанский бриз, мокрые волосы после купания и лёгкую рубашку, накинутую на плечи. Этот аромат словно хранит ощущение свободы и бесконечного лета.\n\nОсобенно понравится тем, кто любит акватическую свежесть без тяжёлой сладости, природные зелёные аккорды и ощущение прохладного воздуха на коже.","notes":{"top":"Итальянский лимон, австралийский прибрежный мох.","middle":"Французский шалфей, египетская герань.","base":"Виргинский кедр, белый мускус.","other":""},"brand":"Goldfield & Banks","name":"Pacific Rock Moss EDP","price3":540,"price5":900,"price10":1800,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/024.webp","placeholder":false},{"id":25,"title":"Les Soeurs de Noé Citrus Poetry Eau de Parfum","tagline":"Цитрусовый · фруктовый · пряный","description":"Citrus Poetry — солнечный день, который хочется продлить ещё хотя бы на несколько часов. Сочный, искристый, бодрый, с яркими цитрусами и пикантной пряностью.\n\nЛимон и имбирь звучат живо и энергично, чёрный перец добавляет озорную остроту. Затем появляется хрустящее яблоко, сладковатый апельсин Cara и нежные лепестки жасмина. Амбра и мох делают финал теплее, оставляя лёгкую зелёную глубину.\n\nПредставьте прогулку по итальянскому побережью: в руках пакет со свежими фруктами, вокруг цитрусовые деревья, от моря тянет ветром, а впереди — длинный ленивый обед на террасе.\n\nCitrus Poetry понравится тем, кто любит жизнерадостные цитрусовые композиции, фруктовую сочность и свежесть, в которой есть характер.","notes":{"top":"Лимон, имбирь, чёрный перец.","middle":"Яблоко, апельсин Cara, лепестки жасмина.","base":"Амбра, мох.","other":""},"brand":"Les Soeurs de Noé","name":"Citrus Poetry EDP","price3":810,"price5":1350,"price10":2700,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/025.webp","placeholder":false},{"id":26,"title":"Mancera Instant Crush Eau de Parfum","tagline":"Амбровый · пряный · цветочный","description":"Instant Crush — аромат мгновенного притяжения. Тёплый, золотистый, пряный, с густой амброй и нежной сладостью, которая постепенно становится почти осязаемой. Он напоминает вечер, когда хочется надеть самое красивое платье, заказать бокал игристого и никуда не торопиться.\n\nВ начале шафран и имбирь добавляют сухую, чуть искристую пряность, а цитрусы дают короткую вспышку света. Затем раскрывается роскошная пара розы и жасмина, утопающая в мягкой амбре. Ваниль, сандал и белый мускус делают шлейф сливочным, бархатным, обволакивающим.\n\nВ нём есть особая праздничность: золотые украшения на тёплой коже, приглушённый свет ресторана, прикосновение кашемира. Instant Crush понравится тем, кто любит насыщенные, сладковато-амбровые композиции с характером и долгим красивым послевкусием.","notes":{"top":"Цитрусы, шафран, имбирь.","middle":"Марокканская роза, египетский жасмин, амбра.","base":"Сандал, дубовый мох, ваниль, белый мускус.","other":""},"brand":"Mancera","name":"Instant Crush EDP","price3":450,"price5":750,"price10":1500,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/026.webp","placeholder":false,"photo_reference_source":"https://parfbar.com/products/mancera-instant-crush.webp"},{"id":27,"title":"Mancera Sicily Eau de Parfum","tagline":"Цитрусовый · фруктовый · цветочный","description":"Sicily пахнет отпуском, в который удалось уехать без обратного билета. Яркий, солнечный, фруктовый — с той беспечной радостью, которую чувствуешь, когда утром открываешь ставни, а за окном уже жарко и пахнет спелыми фруктами.\n\nЦитрусы здесь сочные и бодрые, словно свежевыжатый сок. Яблоко, персик и ананас добавляют сладость спелой мякоти, но не превращают аромат в десерт. Постепенно на первый план выходят жасмин, роза, иланг-иланг и фиалка. Древесина и белый мускус оставляют мягкий, чистый, солнечный след.\n\nЭто белая льняная рубашка поверх загорелых плеч, корзина фруктов на рынке, шумная терраса у моря. Sicily понравится тем, кому хочется яркой фруктовой свежести с нежным цветочным сердцем и ощущением бесконечного лета.","notes":{"top":"Цитрусы, яблоко, персик, ананас.","middle":"Жасмин, роза, иланг-иланг, фиалка.","base":"Сандал, кедр, белый мускус.","other":""},"brand":"Mancera","name":"Sicily EDP","price3":450,"price5":750,"price10":1500,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/027.webp?v=27","placeholder":false},{"id":28,"title":"Parfums de Marly Delina Exclusif Parfum","tagline":"Розовый · фруктовый · амбровый","description":"Delina Exclusif — роза, которой хочется любоваться с близкого расстояния. Не утренняя, прозрачная, покрытая росой, а вечерняя: пышная, бархатная, с мягкой фруктовой сладостью и почти кремовой глубиной.\n\nСначала появляется сочная груша и нежный личи с лёгким цитрусовым оттенком бергамота. Затем распускается дамасская роза — густая, шелковистая, роскошная. Тонкая дымка ладана придаёт ей загадочность, а ваниль, мускус, мох и бобы тонка создают тёплую, округлую базу.\n\nПредставьте шёлковое платье, тяжёлые бархатные портьеры и букет роз в номере красивого старого отеля. Здесь есть романтичность, но без наивности: чувственная, взрослая, уверенная в собственной привлекательности. Delina Exclusif понравится тем, кто любит выразительные розовые ароматы с фруктовой нежностью и роскошным, мягким шлейфом.","notes":{"top":"Бергамот, груша, личи.","middle":"Дамасская роза, ладан.","base":"Ваниль, мускусы, мох, бобы тонка.","other":""},"brand":"Parfums de Marly","name":"Delina Exclusif","price3":1380,"price5":2300,"price10":4600,"priceFull":null,"available":true,"hit":true,"new":false,"image":"assets/products/028.webp","placeholder":false},{"id":29,"title":"Thomas Kosmala No.7 Le Sel de la Terre Eau de Parfum","tagline":"Морской · цитрусовый · древесно-мускусный","description":"Le Sel de la Terre — свежесть, в которой слышится море, а не стиральный порошок. Лимонный, солоноватый, прозрачный, с прохладой морского воздуха и мягкой теплотой чистой кожи.\n\nБергамот и итальянский лимон раскрываются звонко, почти искристо. Морской аккорд добавляет ощущение солёных брызг, а свежие цветочные оттенки делают композицию нежнее. В финале появляются светлая древесина и мускус — спокойные, гладкие, очень приятные.\n\nПредставьте раннее утро на побережье: ещё пустой пляж, прохладные камни под ногами, влажные волосы и белая футболка, которую приятно надеть после душа. Этот аромат понравится тем, кто ищет лёгкую, небанальную свежесть — без тяжёлых аккордов и навязчивой сладости.","notes":{"top":"Бергамот, итальянский лимон, свежий морской аккорд.","middle":"Водный аккорд, свежие цветочные ноты.","base":"Свежие древесные ноты, мускус.","other":""},"brand":"Thomas Kosmala","name":"No.7 Le Sel de la Terre EDP","price3":465,"price5":775,"price10":1550,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/029.webp","placeholder":false},{"id":30,"title":"Tom Ford Ombré Leather Eau de Parfum","tagline":"Кожаный · пряный · цветочный","description":"Ombré Leather — запах дорогой чёрной кожи, согретой телом. Гладкий, глубокий, чуть дымный по настроению, с пряной сухостью и неожиданно красивой цветочной мягкостью. В нём хочется расправить плечи и выбрать одежду, которая сидит безупречно.\n\nКардамон придаёт композиции прохладную пряную грань. В центре — насыщенный аккорд чёрной кожи, которому жасмин самбак добавляет тонкую, почти сливочную цветочность. Пачули, ветивер, мох и амбра делают звучание более тёплым, землистым и объёмным.\n\nПредставьте салон автомобиля с кожаными сиденьями, чёрный пиджак идеального кроя, пустынную дорогу после заката. Здесь нет липкой сладости — есть фактура, тепло и немного дерзости. Ombré Leather понравится тем, кто ценит выразительную кожу, сухие пряности и парфюмерию с узнаваемым характером.","notes":{"top":"Кардамон.","middle":"Кожаный аккорд, жасмин самбак.","base":"Амбра, белый мох, пачули.","other":"Кардамон, аккорд чёрной кожи, жасмин самбак, пачули, белый мох, амбра. В описании бренда также упоминается ветивер. Производитель не разделяет композицию на три ступени."},"brand":"Tom Ford","name":"Ombré Leather EDP","price3":900,"price5":1500,"price10":3000,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/030.webp","placeholder":false},{"id":31,"title":"Marc-Antoine Barrois Ganymede Eau de Parfum","tagline":"Минеральный · кожаный · древесный","description":"Ganymede — аромат, у которого словно нет привычной температуры. Он одновременно прохладный, как отполированный камень, и тёплый, как кожа после долгого дня на солнце. Сухой, солоноватый, воздушный, с удивительно красивой металлической гранью.\n\nСочная искра мандарина быстро встречается с османтусом и бессмертником: появляется тонкая абрикосовая мягкость, пряная сухость и ощущение минеральной замши. Древесный аккорд Akigalawood придаёт композиции объём и современную, почти архитектурную чёткость.\n\nЭто гладкие стены музея современного искусства, белая рубашка необычного кроя, украшения из матового серебра и безупречная осанка. Ganymede понравится человеку, который любит нестандартную красоту, интеллектуальную парфюмерию и ощущение собственной непохожести.\n\nПирамида / ключевые ноты","notes":{"top":"Итальянский мандарин, шафран.","middle":"Китайский османтус, бессмертник, лист фиалки.","base":"Минеральные ноты, замша, акигалавуд, мускус, кедр, пачули.","other":"мандарин, османтус, кожаный аккорд, Akigalawood, бессмертник."},"brand":"Marc-Antoine Barrois","name":"Ganymede EDP","price3":600,"price5":1000,"price10":2000,"priceFull":null,"available":true,"hit":true,"new":false,"image":"assets/products/031.webp","placeholder":false,"photo_reference_source":"https://khrishaperfumery.com.au/cdn/shop/files/marc-antoine-barrois-ganymede-edp-100ml-pos1.webp?v=1780813460&width=1080"},{"id":32,"title":"Dries Van Noten Fleur du Mal Eau de Parfum","tagline":"Фруктовый · цветочный · замшевый","description":"Fleur du Mal — персик, который перестал быть невинным. Не фруктовый компот и не сахарная мякоть, а спелая, бархатистая кожа плода, согретая солнцем. В этой красоте есть что-то чуть запретное, очень тактильное и невероятно притягательное.\n\nПерсиковый сок даёт нежную, влажную сладость. Османтус подхватывает её своим абрикосово-кожаным оттенком, жасмин добавляет мягкую цветочность, а замша делает всё звучание более телесным, гладким и чувственным. Амбра сохраняет тепло, не превращая композицию в тяжёлую сладость.\n\nПредставьте дорогую замшевую сумку, тонкую шёлковую блузу, спелый персик на фарфоровом блюде и вечер, когда хочется быть особенно красивой — прежде всего для себя. Fleur du Mal понравится тем, кто ищет в фруктовых ароматах не легкомыслие, а взрослую, сложную чувственность.\n\nПирамида / ключевые ноты","notes":{"top":"персиковый сок.","middle":"османтус, жасмин.","base":"замша, амбра.","other":""},"brand":"Dries Van Noten","name":"Fleur du Mal EDP","price3":2400,"price5":4000,"price10":8000,"priceFull":null,"available":true,"hit":false,"new":false,"image":"https://theparfums.com/cdn/shop/files/FLEUR_DU_MAL.png?v=1768533705&width=1445","placeholder":false},{"id":33,"title":"Yves Saint Laurent Libre Eau de Parfum Intense","tagline":"Цветочный · лавандовый · ванильный","description":"Libre Intense — тёплая, уверенная женственность с красивой порцией дерзости. Здесь нет застенчивой цветочной нежности: аромат насыщенный, золотистый, сливочно-ванильный, с узнаваемой прохладой лаванды.\n\nЛаванда придаёт композиции строгую, почти костюмную собранность. Цветок апельсина делает её солнечной и чувственной, орхидейный аккорд добавляет объём, а ваниль постепенно смягчает контрасты. Получается необычное сочетание дисциплины и удовольствия — будто идеально скроенный жакет на голое тело.\n\nЭто вечерний город, распущенные волосы после рабочего дня, серьги, которые вы надеваете просто потому, что сегодня хочется. Libre Intense понравится тем, кто любит выразительные цветочно-ванильные ароматы, заметный характер и элегантность без лишней скромности.\n\nПирамида / ключевые ноты","notes":{"top":"Лаванда, мандарин, бергамот.","middle":"Лаванда, цветок апельсина, жасмин самбак, орхидея.","base":"Мадагаскарская ваниль, бобы тонка, амбра, ветивер.","other":"французская лаванда, марокканский цветок апельсина, орхидейный аккорд, ваниль бурбон."},"brand":"Yves Saint Laurent","name":"Libre EDP Intense","price3":750,"price5":1250,"price10":2500,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/033.webp","placeholder":false},{"id":34,"title":"Yves Saint Laurent Y Eau de Parfum","tagline":"Свежий · ароматический · древесный","description":"Y Eau de Parfum — свежесть с характером и хорошими манерами. Собранный, энергичный, чистый, с прохладной зеленью и тёплой древесной глубиной. В нём есть ощущение человека, который умеет выглядеть убедительно и в футболке, и в идеально сидящем костюме.\n\nШалфей даёт яркую травянистую свежесть, герань добавляет звонкую зелёную грань. Затем проявляются чувственные древесные оттенки и тёплые бобы тонка — они делают композицию мягче и привлекательнее, сохраняя её бодрый ритм.\n\nЭто ранняя встреча в городе, свежевыглаженная рубашка, чистый салон автомобиля, уверенное рукопожатие и планы на большой день. Y понравится тем, кто любит современную мужскую свежесть — не водянистую, а плотную, ухоженную, с красивым древесным продолжением.\n\nПирамида / ключевые ноты","notes":{"top":"Яблоко, имбирь, бергамот.","middle":"Шалфей, ягоды можжевельника, герань.","base":"Амбровая древесина, бобы тонка, кедр, ветивер, ладан.","other":"шалфей, герань, древесный аккорд, бобы тонка."},"brand":"Yves Saint Laurent","name":"Y EDP","price3":510,"price5":850,"price10":1700,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/034.webp","placeholder":false},{"id":35,"title":"Maison Margiela Replica Lazy Sunday Morning Eau de Toilette","tagline":"Чистый · цветочный · мускусный","description":"Lazy Sunday Morning — запах утра, в которое никто никуда не торопится. Мягкий, прозрачный, чуть пудровый, с нежностью чистого белья и кожи, ещё хранящей тепло постели. Здесь нет показной нарядности — только редкое удовольствие быть в покое.\n\nГруша, ландыш и альдегиды создают светлое, прохладное начало. Ирис добавляет деликатную пудровость, роза и апельсиновый цвет — тонкую цветочную мягкость. Амбретта и белые мускусы оставляют ощущение свежей хлопковой ткани, а пачули придают композиции едва заметную глубину.\n\nЭто открытое окно, солнечный квадрат на простыне, чашка кофе на прикроватном столике и любимая белая рубашка. Lazy Sunday Morning понравится тем, кто выбирает ароматы близости, уюта и безупречной чистоты, а не громких впечатлений.\n\nПирамида / ключевые ноты","notes":{"top":"груша, ландыш, альдегиды.","middle":"ирис, роза, цветок апельсина.","base":"индонезийские пачули, семена амбретты, белые мускусы.","other":""},"brand":"Maison Margiela","name":"Replica Lazy Sunday Morning","price3":480,"price5":800,"price10":1600,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/035.webp","placeholder":false},{"id":36,"title":"Louis Vuitton Symphony — Extrait de Parfum","tagline":"Цитрусовый · пряный · сияющий","description":"Symphony — это ощущение утра, которое начинается не с будильника, а с открытых окон на море. Воздух прозрачный, солнце уже согревает плечи, а в бокале — свежий сок с терпкой горчинкой цедры. Здесь столько света и движения, что хочется отменить все планы и просто наслаждаться моментом.\n\nГрейпфрут даёт сочную, чуть горьковатую искру, бергамот делает её изящнее, а имбирь добавляет живую, пикантную остроту. В этом аромате нет привычной тяжёлой сладости: он переливается свежестью, оставляя впечатление ухоженности, лёгкости и очень красивого вкуса.\n\nSymphony понравится тем, кто ищет не просто цитрусовый аромат, а ощущение дорогого отдыха, свободы и безупречно свежего воздуха.\n\nНоты и аккорды","notes":{"top":"Грейпфрут, бергамот, апельсин (основной цитрусовый аккорд).","middle":"Имбирь (цитрусово-пряное звучание).","base":"Стойкий цитрусово-имбирный аккорд; отдельные базовые ноты производителем не заявлены.","other":"грейпфрут, имбирь, бергамот. В описании бренда также упоминается апельсин. Производитель не публикует классическую трёхступенчатую пирамиду."},"brand":"Louis Vuitton","name":"Symphony","price3":3300,"price5":5500,"price10":11000,"priceFull":null,"available":true,"hit":true,"new":false,"image":"assets/products/036.webp","placeholder":false},{"id":37,"title":"Valentino Uomo Born in Roma — Eau de Toilette","tagline":"Древесный · ароматический · минеральный","description":"Born in Roma — это мужчина, который одинаково органично выглядит в идеально сидящем пиджаке и простой футболке. Он любит красивые вещи, но не нуждается в подсказках, как их носить. В его стиле есть итальянская лёгкость, а в характере — уверенная независимость.\n\nСвежесть листа фиалки здесь не цветочная в привычном смысле, а прохладная, зелёная, почти минеральная. Шалфей добавляет сухую ароматическую терпкость, имбирь — пряное движение, а дымный ветивер придаёт композиции глубину. Солоноватый оттенок делает аромат особенно современным.\n\nЭто чистый, собранный, привлекательный запах без излишней сладости. Для тех, кому нравится сочетание аккуратности, харизмы и небольшой дерзости.\n\nНоты и аккорды","notes":{"top":"лист фиалки.","middle":"шалфей.","base":"ветивер.","other":"Дополнительные акценты в описании бренда: минеральная соль и имбирь."},"brand":"Valentino","name":"Uomo Born in Roma","price3":450,"price5":750,"price10":1500,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/037.webp","placeholder":false},{"id":38,"title":"Versace Crystal Emerald — Eau de Parfum","tagline":"Цветочный · фруктовый · мускусный","description":"Crystal Emerald напоминает женщину, которая умеет получать удовольствие от собственной красоты. Сочная, яркая, немного кокетливая композиция с ощущением шёлковой блузы, свежего маникюра и внезапного приглашения на свидание.\n\nСначала появляется спелый персик: мягкий, бархатистый, словно его только что разрезали. Бергамот добавляет свежести, розовый перец — лёгкого озорства. Затем раскрываются нежные бутоны роз, жасмин и прохладный малиновый сорбет. Мускус делает аромат гладким и телесным, бобы тонка добавляют тепло, а тонкий ладан не даёт сладости стать слишком простой.\n\nCrystal Emerald понравится любителям женственных фруктово-цветочных ароматов, в которых есть и нежность, и характер, и маленькое обещание праздника.\n\nНоты и аккорды","notes":{"top":"бергамот, персик, розовый перец.","middle":"зелёные бутоны роз, жасмин, малиновый сорбет.","base":"белый мускус, ладан, бобы тонка.","other":""},"brand":"Versace","name":"Crystal Emerald EDP","price3":450,"price5":750,"price10":1500,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/038.webp","placeholder":false},{"id":39,"title":"Jean Paul Gaultier Le Male Elixir — Parfum","tagline":"Амбровый · сладкий · ароматический","description":"Le Male Elixir пахнет тёплой кожей, вечерними огнями и тем самым свиданием, после которого не хочется сразу возвращаться домой. Плотный, сладковато-пряный, обволакивающий — аромат с очень чувственным настроением.\n\nЛаванда даёт узнаваемую прохладную ароматическую грань, но быстро оказывается в объятиях густой сладости бобов тонка. Бензоин добавляет смолистое, почти ванильное тепло. Получается контраст свежести и горячей, уютной глубины: будто прохладный вечер и кашемировый свитер, который ещё хранит тепло тела.\n\nДля тех, кто любит насыщенные, соблазнительные ароматы с мягкой сладостью, выразительным характером и атмосферой ночного города.\n\nНоты и аккорды","notes":{"top":"Лаванда, мята.","middle":"Ваниль, бензоин.","base":"Мёд, бобы тонка, табак.","other":"лаванда, бобы тонка, бензоин. Указаны как основные ноты, без подтверждённого разделения на классическую пирамиду."},"brand":"Jean Paul Gaultier","name":"Le Male Elixir","price3":360,"price5":600,"price10":1200,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/039.webp","placeholder":false},{"id":40,"title":"Escentric Molecules Escentric 02 — Eau de Toilette","tagline":"Минеральный · амбровый · свежий","description":"Escentric 02 сложно сравнить с обычными духами. Он напоминает запах чистой кожи после душа, прохладного воздуха в современной галерее и белой рубашки, которую хочется носить каждый день. В нём есть что-то почти невесомое, но удивительно притягательное.\n\nВ центре композиции — амброксан с гладкой, минеральной, слегка солоноватой теплотой. Зелёный жасмин придаёт живую прозрачность, а искристый аккорд джина с тоником добавляет бодрящую, почти игристую свежесть. Аромат то кажется близким к коже, то снова становится заметным — и в этом его особенное очарование.\n\nEscentric 02 понравится тем, кто устал от очевидной сладости и хочет аромат, который ощущается как собственный, только чуть более интересный запах кожи.\n\nНоты и аккорды","notes":{"top":"Мандарин, лайм, бергамот, ягоды можжевельника, травяной аккорд Almdudler.","middle":"Имбирь, фрезия, шалфей мускатный, розовый перец, гедион, ирис.","base":"Амброксан, мускон (мускус), ветивер, бобы тонка.","other":"амброксан, зелёные бутоны жасмина, аккорд джина с тоником, оттенок Almdudler. Это Escentric 02, не Molecule 02 и не версия Extrait."},"brand":"Escentric Molecules","name":"Escentric 02","price3":null,"price5":null,"price10":null,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/040.webp","placeholder":false},{"id":41,"title":"Juliette Has a Gun — Not a Perfume","tagline":"Древесный · мускусный · амбровый","description":"Not a Perfume — аромат, который хочется почувствовать не на блоттере, а на коже человека, к которому испытываешь симпатию.\n\nПредставьте: чистая кожа после душа, мягкая белая футболка, распущенные волосы и утро, в котором можно никуда не спешить. Ничего нарочитого, ничего лишнего. Только удивительно приятное ощущение близости.\n\nВ основе композиции — цеталокс. Он создаёт тонкое, прозрачное, древесно-мускусное звучание с мягкой амбровой теплотой. Аромат будто становится частью кожи, подчёркивая её естественный запах.\n\nВ нём есть особенная интимность. Не вечернее платье и бриллианты, а любимый человек рядом, прикосновение к плечу и желание задержаться в объятиях ещё на несколько минут.\n\nNot a Perfume понравится тем, кто любит деликатную, чистую, телесную парфюмерию и не хочет выбирать между ароматом и ощущением собственной кожи.","notes":{"top":"Цеталокс (единственный заявленный ароматический компонент).","middle":"Цеталокс (та же молекула на протяжении всего раскрытия).","base":"Цеталокс (чистый мускусно-древесный шлейф).","other":"цеталокс в верхних, сердечных и базовых нотах."},"brand":"Juliette Has a Gun","name":"Not a Perfume","price3":null,"price5":null,"price10":null,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/041.webp","placeholder":false,"photo_reference_source":"https://cdn.timestore.cz/images/w700/8907-1.webp?v=1763678487"},{"id":42,"title":"Позиция №42","tagline":"","description":"","notes":{"top":"","middle":"","base":"","other":""},"brand":"Уточняется","name":"Позиция №42","price3":null,"price5":null,"price10":null,"priceFull":null,"available":false,"hit":false,"new":false,"image":null,"placeholder":true},{"id":43,"title":"Roja — Elysium Pour Homme Eau de Parfum","tagline":"Цитрусовый · ароматический · древесный","description":"Elysium — аромат мужчины, который привык к хорошей жизни и умеет получать от неё удовольствие.\n\nПредставьте красивое утро на Лазурном Берегу. Белая льняная рубашка, прохладный воздух с моря, крепкий кофе на террасе и впереди целый день, который принадлежит только вам.\n\nАромат начинается ярко и энергично: сочный грейпфрут, искристый лимон, бергамот и лайм встречаются с прохладной лавандой и пряными травами. Затем появляются яблоко, чёрная смородина и тонкие цветочные оттенки.\n\nПостепенно эта свежесть становится благороднее и глубже. Кедр, ветивер, можжевельник, кожа и мягкие амбровые оттенки создают красивое, уверенное древесное звучание.\n\nElysium — про свободу, великолепный вкус и мужскую привлекательность, которой не требуется специальный повод.\n\nОсобенно понравится любителям свежих, многогранных, дорогих по звучанию композиций с выразительной древесной базой.","notes":{"top":"лимон, бергамот, грейпфрут, лайм, лаванда, тимьян, полынь, мускус.","middle":"ландыш, майская роза, жасмин из Грасса, яблоко, чёрная смородина.","base":"гальбанум, розовый перец, киприол, ветивер, кедр, можжевельник, бензоин, ваниль, лабданум, кожа, амбра, мускус.","other":""},"brand":"Roja","name":"Elysium Pour Homme EDP","price3":1110,"price5":1850,"price10":3700,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/043.webp","placeholder":false},{"id":44,"title":"Xerjoff — 1861 Naxos Eau de Parfum","tagline":"Медовый · пряный · табачный","description":"Naxos — аромат, в котором итальянская страсть встречается с невероятной элегантностью.\n\nПредставьте Сицилию в конце августа. Солнце уже опускается за старинные здания, воздух всё ещё тёплый, на столе бокал вина, а впереди длинный вечер, который совершенно не хочется заканчивать.\n\nВ начале — освежающий бергамот, лимон и ароматная лаванда. Но постепенно композиция становится густой, золотистой, почти съедобной. Появляются тягучий мёд, пряная корица, нежный жасмин и мягкие кашемировые оттенки.\n\nА дальше начинается самое красивое: благородный табачный лист, сливочная ваниль и бобы тонка. Они создают насыщенный, согревающий, бархатистый шлейф.\n\nВ Naxos есть особенная чувственность. Он напоминает дорогой кашемир, загорелую кожу, красивые итальянские интерьеры и долгие поцелуи после ужина.\n\nЭтот аромат понравится тем, кто любит богатые, сладковато-пряные, выразительные композиции, в которых сладость приобретает взрослый, благородный характер.","notes":{"top":"лимон, бергамот, лаванда, оманский ладан.","middle":"жасмин самбак, мёд, корица, кашемировый аккорд.","base":"ваниль, табачный лист, бобы тонка.","other":""},"brand":"Xerjoff","name":"1861 Naxos EDP","price3":840,"price5":1400,"price10":2800,"priceFull":null,"available":true,"hit":true,"new":false,"image":"assets/products/044.webp","placeholder":false,"photo_reference_source":"https://fumeimg-21439.kxcdn.com/fumeimg/186272/8b468ec55c94e28531274819bc738fc8/detailsc/naxos-edp-100ml_1.jpg"},{"id":45,"title":"Chanel — Chance Eau Tendre Eau de Parfum","tagline":"Цветочный · фруктовый · нежный","description":"Chance Eau Tendre — аромат женщины, в которую легко влюбиться. И совершенно необязательно с первого взгляда.\n\nПредставьте Париж весной. Лёгкое платье, свежий букет цветов, утренний кофе и то самое настроение, когда хочется улыбаться незнакомым людям просто потому, что жизнь прекрасна.\n\nКомпозиция нежная, воздушная, светлая. В её сердце — роскошный жасмин и изящная роза. Цветы звучат мягко, свежо и удивительно естественно, создавая ощущение красивой, ухоженной женственности.\n\nЗдесь нет тяжёлой сладости или избыточной насыщенности. Chance Eau Tendre напоминает нежное прикосновение, свежие простыни, светлую комнату с открытыми окнами и первые минуты счастливого свидания.\n\nОн особенно красив в своей деликатности. Это аромат романтичной, обаятельной женщины, которая умеет наслаждаться простыми вещами и превращать обычный день в маленький праздник.\n\nИдеальный выбор для любителей нежных, изящных, цветочно-фруктовых композиций.","notes":{"top":"Айва, грейпфрут.","middle":"Роза, жасмин.","base":"Белый мускус.","other":"абсолют жасмина и эссенция розы. Chanel не публикует для этой версии полную трёхступенчатую пирамиду."},"brand":"Chanel","name":"Chance Eau Tendre EDP","price3":810,"price5":1350,"price10":2700,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/045.webp","placeholder":false},{"id":46,"title":"Chanel — Chance Eau Splendide Eau de Parfum","tagline":"Малиновый · цветочный · пудровый","description":"Chance Eau Splendide — аромат женщины, которая умеет быть счастливой красиво.\n\nПредставьте неожиданное приглашение на свидание. Вы ещё не решили, что наденете, но уже улыбаетесь своему отражению. Впереди приятное волнение, немного флирта и предчувствие чего-то прекрасного.\n\nАромат начинается сочной, искристой малиной с тонкими оттенками розы и фиалки. Она яркая, аппетитная, но при этом удивительно изящная.\n\nВ сердце раскрывается розовая герань с лёгкой прохладной свежестью. Затем появляется нежный пудровый ирис, а кедр и белый мускус придают композиции мягкость и элегантность.\n\nChance Eau Splendide напоминает розовый шёлк, свежую ягодную корзину, красивую помаду и весёлый вечер, который неожиданно становится особенным.\n\nОн понравится тем, кто любит женственные, кокетливые, фруктово-цветочные ароматы с утончённым пудровым послевкусием.","notes":{"top":"Малина, красные ягоды, роза, фиалка, персик.","middle":"Розовая герань, ирис.","base":"Белый мускус, кедр.","other":"малина с оттенками розы и фиалки, розовая герань, ирис, кедр, белый мускус. Chanel не разделяет их на полную классическую пирамиду."},"brand":"Chanel","name":"Chance Eau Splendide EDP","price3":810,"price5":1350,"price10":2700,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/046.webp","placeholder":false},{"id":47,"title":"Позиция №47","tagline":"","description":"","notes":{"top":"","middle":"","base":"","other":""},"brand":"Уточняется","name":"Позиция №47","price3":null,"price5":null,"price10":null,"priceFull":null,"available":false,"hit":false,"new":false,"image":null,"placeholder":true},{"id":48,"title":"BYBOZO Habibi Eau de Parfum","tagline":"Гурманский · зелёный · миндально-вишнёвый","description":"Habibi — аромат, в котором любовь пахнет не букетом цветов, а ощущением, что тебя наконец-то обняли по-настоящему.\n\nПредставьте тихий вечер на средиземноморской вилле. За открытыми окнами пахнет травами, в воздухе ещё держится дневное тепло, а на столе — миска спелой вишни. Никто никуда не торопится, и самое приятное происходит не снаружи, а внутри: вам спокойно, хорошо и удивительно уютно.\n\nЗелёное, чуть прохладное начало постепенно уступает место сочной вишне, нежному миндалю и терпковатому листу красной смородины. Мускус и сандал делают композицию мягкой, сливочной, почти осязаемой — словно любимый кашемировый кардиган, наброшенный на плечи.\n\nHabibi понравится тем, кто любит гурманские ароматы без приторности: тёплые, нежные, телесные, с красивой фруктовой сердцевиной. Это тот случай, когда парфюм хочется подарить человеку, которому трудно подобрать слова о своих чувствах.","notes":{"top":"средиземноморские травы.","middle":"миндаль, вишня, лист красной смородины.","base":"мускус, сандал.","other":""},"brand":"BYBOZO","name":"Habibi EDP","price3":600,"price5":1000,"price10":2000,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/048.webp","placeholder":false},{"id":49,"title":"Lattafa Pride Art of Universe","tagline":"Цитрусовый · свежий · древесно-амбровый","description":"Art of Universe — запах человека, который умеет начинать день с хорошего настроения, даже если на улице понедельник.\n\nПредставьте прохладное утро в большом городе. Вы выходите из отеля с кофе, впереди важная встреча, но вместо напряжения — приятный азарт. Чистая рубашка, уверенная походка, солнце на стеклянных фасадах. Именно такую бодрую, собранную энергию хочется поймать в этом аромате.\n\nБергамот и мандарин дают яркую цитрусовую вспышку, мята добавляет холодка, а имбирь — пикантной остроты. Затем появляется сочная груша и мягкий цветок апельсина. Кедр, амбра и мускус постепенно делают звучание более гладким, тёплым и основательным.\n\nArt of Universe понравится тем, кто любит современную свежесть с характером: энергичную, чистую, привлекательную, но не резкую. Удачный аромат на каждый день, когда хочется чувствовать себя особенно собранно и легко.","notes":{"top":"бергамот, мандарин, имбирь, мята.","middle":"цветок апельсина, груша.","base":"кедр, амбра, мускус.","other":""},"brand":"Lattafa Pride","name":"Art of Universe","price3":360,"price5":600,"price10":1200,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/049.webp","placeholder":false},{"id":50,"title":"Lattafa Pride Art of Nature II","tagline":"Цитрусовый · цветочно-пряный · древесный","description":"Art of Nature II — аромат красивого контраста: свежего воздуха и тёплой кожи, строгой одежды и неожиданно нежного характера.\n\nПредставьте загородный дом после дождя. Вы открываете окно, и в комнату входит прохладный воздух с запахом зелени. На кухне лежат яблоки и мандарины, а рядом — букет свежих цветов. Всё выглядит естественно, спокойно, но в этой простоте есть своя особенная роскошь.\n\nБергамот, мандарин и яблоко делают начало сочным и светлым; ладан добавляет тонкую смолистую глубину. В сердце расцветают роза и флердоранж, согретые кардамоном. А дальше — мягкая ваниль, древесные ноты, амброксан и мускус: уютная, тёплая база, которая красиво контрастирует с искристым стартом.\n\nArt of Nature II понравится тем, кто ищет универсальный, многогранный аромат — свежий, но не холодный; сладковатый, но не десертный; элегантный, но без излишней строгости.","notes":{"top":"бергамот, ладан, мандарин, яблоко.","middle":"цветок апельсина, роза, кардамон.","base":"ваниль, амброксан, гваяковое дерево, кедр, мускус.","other":""},"brand":"Lattafa Pride","name":"Art of Nature II","price3":360,"price5":600,"price10":1200,"priceFull":null,"available":true,"hit":false,"new":false,"image":"https://i5.walmartimages.com/asr/73ca95a6-0238-4069-bf65-90823930e85c.f9bc945d86b7d008ed802c87239ef033.jpeg?odnBg=FFFFFF&odnHeight=768&odnWidth=768","placeholder":false},{"id":51,"title":"Fendi Eaux d’Artifice Eau de Parfum","tagline":"Минеральный · акватический · ароматический","description":"Eaux d’Artifice — аромат Рима, который особенно красив после полуночи.\n\nПредставьте старинную площадь, почти пустую после шумного дня. В свете фонарей мерцает вода фонтана, прохладный мрамор хранит вечернюю свежесть, а на запястье поблёскивает тяжёлый серебряный браслет. Здесь нет привычной сладкой романтики. Здесь — аристократическая дерзость, безупречная осанка и любовь к вещам с историей.\n\nМинерально-водный аккорд создаёт необычное ощущение прохлады, можжевельник добавляет сухую ароматическую свежесть, а средиземноморский кипарис — стройную, благородную зелёную линию. Композиция кажется одновременно прозрачной и насыщенной, как отражение старого дворца в ночной воде.\n\nEaux d’Artifice понравится тем, кто устал от предсказуемых цветов и ванили. Это интеллектуальный, прохладный, необычный аромат для любителей парфюмерии с архитектурой и характером.","notes":{"top":"Можжевельник (ароматическая свежесть).","middle":"Минеральный и акватический аккорды.","base":"Средиземноморский кипарис (древесная составляющая).","other":"Ключевые ноты по версии Fendi: эссенция можжевельника; минерально-акватический аккорд; эссенция средиземноморского кипариса."},"brand":"FENDI","name":"Eaux d’Artifice EDP","price3":2250,"price5":3750,"price10":7500,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/051.webp","placeholder":false},{"id":52,"title":"Coreterno Mystic Sugar Eau de Parfum","tagline":"Тропический · гурманский · пряно-ванильный","description":"Mystic Sugar — аромат, который ведёт себя как запретный десерт: сначала обещает невинное удовольствие, а потом выясняется, что остановиться невозможно.\n\nПредставьте вечер на тропическом острове. Воздух тёплый, на столе — нарезанный ананас, сочные апельсины и шоколадный десерт. Кто-то смеётся, играет музыка, и вы вдруг понимаете, что давно не чувствовали себя настолько свободно. Никаких правил хорошего поведения — только удовольствие от момента.\n\nВ начале сочный ананас и апельсин встречаются с нежным цветком миндаля. Затем появляется густое какао, согретое имбирём, кардамоном, жасмином и бобами тонка. Ваниль, сандал и амбра делают шлейф сливочным, тягучим, бархатистым — словно шоколад медленно тает на тёплой коже.\n\nMystic Sugar понравится любителям смелой гурманики: сладкой, пряной, экзотической, с красивой взрослой чувственностью. Особенно тем, кому обычная ваниль давно кажется слишком послушной.","notes":{"top":"апельсин, цветок миндаля, ананас.","middle":"абсолют какао, кардамон, жасмин, имбирь, бобы тонка.","base":"абсолют ванили, сандал, амбра.","other":""},"brand":"Coreterno","name":"Mystic Sugar EDP","price3":750,"price5":1250,"price10":2500,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/052.webp","placeholder":false},{"id":53,"title":"Nishane Hacivat Extrait de Parfum","tagline":"Цитрусовый · шипровый · древесный","description":"Hacivat — аромат человека, которому нравится побеждать красиво. Не ради чужого одобрения, а ради того удивительного чувства, когда всё получилось именно так, как задумано.\n\nПредставьте утро перед важным событием. Идеально сидящий жакет, прохладный воздух, свежие фрукты на завтраке и спокойная уверенность в собственных силах. Вы ещё не вышли из дома, а настроение уже праздничное.\n\nПервое впечатление — сочный ананас, искристый бергамот и терпковатый грейпфрут. Затем фруктовая яркость становится строже: появляются сухой кедр, пачули и тонкий жасмин. Дубовый мох и древесные оттенки придают композиции плотность, благородную горчинку и узнаваемый шипровый характер.\n\nHacivat понравится тем, кто любит энергичные, выразительные ароматы с красивой фруктовой свежестью и серьёзной древесной основой. В нём удивительно хорошо сочетаются азарт нового дня и ощущение уже достигнутого успеха.","notes":{"top":"бергамот, ананас, грейпфрут.","middle":"жасмин, пачули, кедр.","base":"Clearwood, дубовый мох, сухие древесные ноты (Timberwood).","other":""},"brand":"Nishane","name":"Hacivat","price3":840,"price5":1400,"price10":2800,"priceFull":null,"available":true,"hit":false,"new":false,"image":"https://www.faces.sa/dw/image/v2/BJSM_PRD/on/demandware.static/-/Sites-faces-master-catalog/default/dwb2f9255f/images/PM_NISHANE_hacivat_eau_de_parfum_1.jpg?sh=800&sw=800","placeholder":false},{"id":54,"title":"Genyum Painter Eau de Parfum","tagline":"Пряный · морской · древесный","description":"Painter — аромат для тех, кому тесно в рамках безупречной предсказуемости. В нём есть свобода художника, который не боится испачкать дорогую рубашку краской, если в голове родилась прекрасная идея.\n\nПредставьте мастерскую у моря. Огромные окна, открытые банки с пигментами, шероховатый холст, деревянный стол и прохладный ветер с побережья. Здесь пахнет творчеством, солью на коже и свежим воздухом, а не идеально выверенным интерьером.\n\nЧёрный перец придаёт композиции сухую, звонкую остроту. Морские водоросли ламинария создают необычную прохладную, чуть солоноватую фактуру, а ветивер отвечает за землистую, древесную глубину. Белая амбра и мускус, о которых говорит бренд, смягчают эту выразительную конструкцию.\n\nPainter понравится любителям интеллектуальной, нестандартной свежести. Это не сладкая история о красивой жизни, а аромат живого характера: любопытного, свободного, немного дерзкого и совершенно не похожего на остальные.","notes":{"top":"Чёрный перец.","middle":"Водоросли ламинария.","base":"Ветивер, белая амбра, мускус.","other":"чёрный перец, водоросли ламинария, ветивер."},"brand":"Genyum","name":"Painter EDP","price3":900,"price5":1500,"price10":3000,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/054.webp","placeholder":false},{"id":55,"title":"Ex Nihilo Demon Dancer Eau de Parfum","tagline":"Зелёный · фруктовый · древесно-амбровый","description":"Demon Dancer — аромат вечера, когда вы вдруг перестаёте быть благоразумной версией себя. Не потому, что нужно произвести впечатление. Просто сегодня хочется музыки погромче, движения и свободы.\n\nПредставьте полутёмный зал, ритм, который чувствуется кожей, и то прекрасное мгновение, когда вы перестаёте смотреть на часы. В воздухе — прохлада, энергия, лёгкая дерзость и предвкушение чего-то неожиданного.\n\nРевень даёт сочную, кисловатую, почти электрическую свежесть. Бергамот и красный апельсин добавляют яркости, перечная мята — холодного движения. Затем проявляются флердоранж и чёрная смородина: композиция становится более чувственной, фруктовой, насыщенной. Древесно-амбровая база с мускусом и бобами тонка оставляет тёплое, выразительное послевкусие.\n\nDemon Dancer понравится тем, кто любит контрасты: прохладное и тёплое, свежее и чувственное, энергичное и обволакивающее. Это аромат не для тихого наблюдения за жизнью, а для участия в ней.","notes":{"top":"ревень, бергамот, перечная мята, красный апельсин.","middle":"цветок апельсина, чёрная смородина.","base":"Georgywood™, Akigalawood™, Ambrofix™, мускусы, бобы тонка.","other":""},"brand":"Ex Nihilo","name":"Demon Dancer EDP","price3":1500,"price5":2500,"price10":5000,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/055.webp","placeholder":false},{"id":56,"title":"Henry Perfumery Lab I Eau de Parfum","tagline":"Цитрусовый · пряный · чайно-древесный","description":"Henry I — аромат человека, у которого даже обычное утро выглядит как начало интересного путешествия. В нём есть бодрость свежего цитруса, интеллигентная пряность и особенное удовольствие от неспешных ритуалов.\n\nПредставьте маленький отель в незнакомом городе. За окном только просыпаются улицы, на столике — чашка крепкого чёрного чая, а в открытое окно входит прохладный воздух. Вы ещё не знаете, куда пойдёте после завтрака, и именно это делает утро таким прекрасным.\n\nЦитрон, калабрийский бергамот и апельсин создают сочное, солнечное начало. Тунисский нероли добавляет изящной цветочной свежести, имбирь — искристой остроты, цейлонская корица — деликатного тепла. В базе китайский чёрный чай встречается с амброксаном и древесным ладаном: аромат становится глубже, суше и благороднее.\n\nHenry I понравится тем, кто любит свежие композиции, но хочет от них большего, чем просто ощущение чистоты. Здесь есть характер, тонкая пряность, чайная терпкость и настроение человека, которому всегда интересно жить.","notes":{"top":"цитрон, калабрийский бергамот, апельсин.","middle":"тунисский нероли, имбирь, цейлонская корица.","base":"китайский чёрный чай, амброксан, древесный ладан.","other":""},"brand":"Henry Perfumery Lab","name":"I EDP","price3":750,"price5":1250,"price10":2500,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/056.webp","placeholder":false},{"id":57,"title":"Attar Collection Idol Extrait de Parfum","tagline":"Морской · цветочный · древесно-мускусный","description":"Idol — аромат человека, который умеет быть притягательным без лишней театральности. В нём есть прохлада морского воздуха, чистота белых цветов и мягкое тепло дорогой ткани, нагретой солнцем.\n\nПредставьте утро на яхте. Белая рубашка чуть касается загорелой кожи, ветер перебирает волосы, море кажется бесконечным, а впереди — день, в котором можно никуда не торопиться. Всё просто, красиво и удивительно спокойно.\n\nБергамот придаёт началу свежесть, ландыш — нежную цветочную прозрачность, а морской аккорд — ощущение прохладного бриза. Затем появляются белые цветы, шалфей и мягкий кашмеран. Древесные, мшистые и амбровые оттенки делают звучание более глубоким, тёплым и тактильным.\n\nIdol понравится любителям свежих, элегантных, не слишком сладких ароматов, которые напоминают о чистой коже, морском воздухе и красивом отдыхе. В нём нет суеты — только ощущение, что всё самое приятное уже рядом.","notes":{"top":"бергамот, ландыш, морской бриз.","middle":"кашмеран, мускатный шалфей, белые цветы.","base":"амбра (ambergris), кедр, мох.","other":""},"brand":"Attar Collection","name":"Idol","price3":810,"price5":1350,"price10":2700,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/057.webp","placeholder":false},{"id":58,"title":"Brunello Cucinelli Pour Femme Eau de Parfum","tagline":"Цитрусовый · древесный · кашемирово-мягкий","description":"Pour Femme — аромат женщины, для которой роскошь начинается с ощущения ткани на коже, а не с названия на этикетке.\n\nПредставьте раннее утро в Умбрии. Из распахнутого окна тянет свежим воздухом, на плечах тонкий кашемировый кардиган, в чашке — горячий кофе. Вы никуда не спешите, и именно поэтому выглядите особенно красиво. Здесь нет случайных деталей: всё спокойно, светло, благородно.\n\nКалабрийский бергамот и сицилийский мандарин делают начало искристым и сочным; розовый перец добавляет лёгкую пикантность. Затем появляется нежный флердоранж и необычная мягкость каштана. Кедровая древесина, ветивер, ладан, амброкс и мускус создают тонкий, тёплый, ухоженный шлейф.\n\nPour Femme понравится тем, кто любит дорогую простоту: чистые линии, натуральные ткани, мягкую древесность и элегантность, которая никогда не выглядит нарочитой.","notes":{"top":"розовый перец, калабрийский бергамот, сицилийский мандарин.","middle":"цветок апельсина, каштан, атласский и виргинский кедр.","base":"гаитянский ветивер, ладан, Ambrox Super, мускус.","other":"Статус проверки: Официальный сайт бренда подтверждает образ и характер композиции; подробная разбивка нот сверена с Harrods (не официальный сайт производителя)."},"brand":"Brunello Cucinelli","name":"Pour Femme EDP","price3":900,"price5":1500,"price10":3000,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/058.webp","placeholder":false},{"id":59,"title":"Urban Scents Wiegenlied / Lullaby Eau de Parfum","tagline":"Розовый · цитрусовый · пряно-мускусный","description":"Lullaby — аромат воспоминания, которое вы храните бережнее старых фотографий.\n\nПредставьте вечер, когда за окном идёт дождь. В комнате горит только одна лампа, играет тихая музыка, на столе лежит письмо, которое вы почему-то так и не выбросили. Есть чувства, которые со временем становятся мягче, но не исчезают. Именно о такой нежности рассказывает Lullaby.\n\nВ центре композиции — деликатная роза. Её окружают прозрачные цитрусовые оттенки и мягкие специи, а мускус придаёт запаху удивительную телесность: словно аромат любимого человека остался на подушке. Здесь нет тяжёлой драматичности — только светлая ностальгия, тепло и едва заметная грусть.\n\nЭто красивый выбор для тех, кому близка интимная, утончённая парфюмерия: не сладкий комплимент окружающим, а собственная маленькая история любви.","notes":{"top":"Сычуаньский перец, бергамот, гвоздика, перец тимут.","middle":"Нероли, роза Грасса.","base":"Мускус, аккорд чистой кожи, чистые ноты.","other":"роза, цитрусовые ноты, мягкие специи, выраженный мускусный аккорд."},"brand":"Urban Scents","name":"Wiegenlied / Lullaby EDP","price3":1650,"price5":2750,"price10":5500,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/059.webp","placeholder":false},{"id":60,"title":"Bouge Pathos","tagline":"Пряный · цветочно-замшевый · древесный","description":"Pathos — аромат красивой дерзости. Той самой, которая не нуждается ни в громком голосе, ни в разрешении.\n\nПредставьте вечер в галерее современного искусства. Строгий чёрный костюм, крупное украшение, приглушённый свет, бокал в руке. Вы смотрите на необычную картину и понимаете: она вам нравится именно потому, что не пытается быть понятной всем.\n\nВ начале — сочный итальянский мандарин и сухие, горячие специи: шафран, перец, мускатный орех. Затем появляется бархатистая фиалка, фруктово-кожаный османтус и смолистый лабданум. Мягкая замша, пачули, дубовый мох и сандал создают глубокую, тактильную, слегка загадочную основу.\n\nPathos понравится тем, кто любит выразительную древесно-замшевую парфюмерию с необычным характером. Не романтичный букет, а тщательно выбранный образ, в котором каждая деталь имеет значение.","notes":{"top":"итальянский мандарин, шафран, перец, мускатный орех.","middle":"фиалка, османтус, лабданум, мускус.","base":"замша, пачули, дубовый мох, сандал.","other":"Статус проверки: Полную пирамиду удалось подтвердить по профильным парфюмерным источникам; официальную страницу производителя с этой пирамидой не удалось проверить. Не маркировать как официальную."},"brand":"Bouge","name":"Pathos","price3":360,"price5":600,"price10":1200,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/060.webp","placeholder":false},{"id":61,"title":"Maison Margiela Replica Jazz Club Eau de Toilette","tagline":"Ромовый · табачный · древесно-ванильный","description":"Jazz Club — аромат вечера, который начинается с одного коктейля, а заканчивается историей, которую ещё долго будут вспоминать.\n\nПредставьте небольшой джазовый бар в Бруклине. Низкий свет, потёртые кожаные кресла, музыка, от которой хочется прикрыть глаза. На столе бокал тёмного рома, в воздухе — тёплый, чуть дымный запах табака. Всё вокруг словно создано для неспешного разговора и опасно приятного флирта.\n\nРозовый перец, лимон и нероли дают искристое пряное начало. Затем раскрываются насыщенный ром, шалфей и ветивер. А в базе остаются табачный лист, смолистый стиракс и мягкая ваниль — тёплые, густые, обволакивающие оттенки, которые хочется вдыхать снова.\n\nJazz Club понравится тем, кто любит атмосферные, взрослые, слегка богемные ароматы. Он не про безупречную дневную свежесть, а про удовольствие от ночи, в которой ещё столько всего может случиться.","notes":{"top":"розовый перец, лимон Primofiore, нероли.","middle":"абсолют рома, мускатный шалфей, яванский ветивер.","base":"стиракс, абсолют табачного листа, ваниль.","other":"Статус проверки: Официальный сайт Maison Margiela. Концентрация — Eau de Toilette."},"brand":"Maison Margiela","name":"Replica Jazz Club","price3":450,"price5":750,"price10":1500,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/061.webp","placeholder":false},{"id":62,"title":"Attar Collection Sierra Eau de Parfum","tagline":"Пряный · цветочный · древесно-смолистый","description":"Sierra — аромат человека, в котором удивительным образом уживаются нежность и характер.\n\nПредставьте вечер после долгого путешествия. Вы открываете окна номера, за ними — тёплый город, огни и едва уловимый ветер. На столе стоят цветы, но вы выбираете не романтичную открытку, а настоящую жизнь: яркую, непредсказуемую, полную впечатлений.\n\nРозовый перец и имбирь дают пряное, бодрое начало. В сердце раскрывается мягкий османтус с его бархатистой фруктово-цветочной теплотой; современные цветочные молекулы добавляют воздушности. Бобы тонка, ладан и кедр создают глубокий, согревающий, чуть дымный шлейф.\n\nSierra понравится тем, кто ищет выразительную композицию на границе цветочной нежности и восточной пряности. Она одновременно уютная и интригующая — как человек, с которым всегда интересно.","notes":{"top":"розовый перец, имбирь.","middle":"османтус, Pomarose, Rosyfolia, Mahonial.","base":"бобы тонка, ладан, кедр, Georgywood.","other":"Статус проверки: Официальный сайт Attar Collection."},"brand":"Attar Collection","name":"Sierra EDP","price3":450,"price5":750,"price10":1500,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/062.webp","placeholder":false},{"id":63,"title":"Dries Van Noten Soie Malaquais Eau de Parfum","tagline":"Шёлковый · каштановый · шоколадно-цветочный","description":"Soie Malaquais — аромат женщины, у которой даже прикосновение к ткани превращается в маленькое искусство.\n\nПредставьте парижскую квартиру с высокими потолками. На спинке кресла лежит шёлковое платье, в вазе — розы, а на столе остывает чашка густого какао. За окном уже темнеет, но вечер только обещает стать интересным.\n\nБергамот и чёрная смородина дают лёгкую свежую искру. Затем появляется роза, окутанная нежным шёлковым аккордом. А в глубине — каштан и какао: тёплые, ореховые, чуть горьковатые, удивительно тактильные.\n\nЭто не обычный сладкий аромат. В нём есть дорогая фактура, мягкая чувственность и немного артистической непредсказуемости. Soie Malaquais понравится тем, кто любит необычную гурманику и умеет ценить красоту деталей.","notes":{"top":"бергамот, чёрная смородина.","middle":"роза, шёлковый аккорд.","base":"каштан, какао.","other":""},"brand":"Dries Van Noten","name":"Soie Malaquais EDP","price3":2250,"price5":3750,"price10":7500,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/063.webp","placeholder":false},{"id":64,"title":"ELLA K Mémoire de Daïsen In Eau de Parfum","tagline":"Розовый · минеральный · древесно-мускусный","description":"Mémoire de Daïsen In — аромат тишины, в которой неожиданно начинаешь лучше слышать себя.\n\nПредставьте Киото ранним утром. За деревянными воротами скрывается сад камней. На дорожке ещё лежит прохлада, рядом распускаются пионы и розы, а где-то вдалеке слышны едва различимые шаги. В таком месте хочется говорить шёпотом — не из вежливости, а потому что всё вокруг слишком красиво для лишних слов.\n\nКумкват и бергамот дают светлое цитрусовое начало, мускатный орех добавляет тонкую пряность. В сердце раскрываются роза Alba и пион, окружённые мягким мускусом. Амброксан и древесина клёна оставляют чистое, прозрачное, чуть минеральное послевкусие.\n\nЭтот аромат понравится тем, кто ищет в парфюмерии не эффектное заявление, а состояние: спокойствие, ясность, изящество и внутреннюю гармонию.","notes":{"top":"кумкват, бергамот, мускатный орех.","middle":"роза Alba, пион, мускус.","base":"амброксан, древесина клёна.","other":""},"brand":"Ella K","name":"Mémoire de Daïsen In EDP","price3":600,"price5":1000,"price10":2000,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/064.webp","placeholder":false},{"id":65,"title":"HFC Musk Flower Eau de Parfum","tagline":"Цветочный · мускусный · фруктово-древесный","description":"Musk Flower — аромат солнечного дня, когда хочется быть красивой исключительно для собственного удовольствия.\n\nПредставьте Лазурный Берег. Лёгкий ветер шевелит занавески, на террасе стоят пионы, а в бокале тает лёд. Вы только что вернулись с прогулки у моря, кожа ещё хранит тепло солнца, и впереди нет ни одного обязательного дела.\n\nРевень даёт пикантную кислинку, малина — нежную ягодную сочность, а фиалка и пион делают начало воздушным. Роза, гвоздика и ветивер добавляют композиции глубины, мускус — ощущения чистой тёплой кожи. В базе появляются сандал, бобы тонка, тонкие кожаные и дымные оттенки.\n\nMusk Flower понравится любителям цветочных ароматов с характером: свежих, но не холодных, нежных, но не простодушных. В нём много света, мягкости и очень красивой телесности.","notes":{"top":"малина, фиалка, ревень, пион.","middle":"мускус, роза, ветивер, гвоздика.","base":"бобы тонка, кожа, сандал, дымный аккорд.","other":""},"brand":"HFC","name":"Musk Flower EDP","price3":1350,"price5":2250,"price10":4500,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/065.webp","placeholder":false},{"id":66,"title":"Cherigan Lovers in Pink Extrait de Parfum","tagline":"Игристый · ягодно-цветочный · древесно-мускусный","description":"Lovers in Pink — аромат влюблённости, когда даже обычный вторник кажется началом красивого романа.\n\nПредставьте Париж двадцатых годов. В мастерской художника на полу лежат холсты, на столе — свежие цветы и бокалы шампанского. За окном город живёт своей жизнью, а внутри кто-то смотрит на любимого человека так, словно впервые увидел настоящий цвет.\n\nЧёрная смородина, лимон и имбирь создают искристое, почти шампанское начало. Затем раскрывается пышный букет жасмина, роз и пионов — яркий, романтичный, живой. Кедр и мускус придают цветам мягкость и красивую глубину.\n\nВдохновением для Lovers in Pink стали образы Беллы — жены и музы Марка Шагала. Аромат понравится тем, кто любит сочные цветочные композиции, кокетливое настроение и ощущение праздника без особого повода.","notes":{"top":"имбирь, цитрусовые эссенции, почки кассии; бренд также выделяет аккорд чёрной смородины.","middle":"абсолют жасмина, роза, пион.","base":"кедр, мускус.","other":""},"brand":"Cherigan","name":"Lovers in Pink","price3":1200,"price5":2000,"price10":4000,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/066.webp","placeholder":false},{"id":67,"title":"BDK Parfums Impadia Eau de Parfum","tagline":"Розовый · ванильный · сливочно-древесный","description":"Impadia — аромат женщины, которая умеет превращать обычный день в повод надеть любимое платье.\n\nПредставьте Париж в час заката. Каменные фасады становятся медовыми, окна отражают розовое небо, в саду ещё пахнут цветы. Вы идёте на ужин, и вечер кажется обещанием чего-то невероятно приятного.\n\nСочный мандарин, бергамот и груша создают сияющее фруктовое начало. Затем раскрываются две роскошные розы — болгарская и турецкая — вместе с нежным цветком апельсина. Ваниль, сандал и акигалавуд делают композицию тёплой, сливочной и бархатистой. В общем впечатлении чувствуется почти десертная мягкость, но цветы сохраняют её элегантность.\n\nImpadia понравится тем, кто любит женственные, насыщенные розово-ванильные ароматы с современным древесным характером. Красивый выбор для свиданий, праздников и тех дней, когда хочется немного больше роскоши.","notes":{"top":"итальянский мандарин, итальянский бергамот, груша.","middle":"болгарская роза, абсолют турецкой розы, абсолют цветка апельсина.","base":"акигалавуд, абсолют ванили, сандал.","other":""},"brand":"BDK Parfums","name":"Impadia EDP","price3":1200,"price5":2000,"price10":4000,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/067.webp","placeholder":false},{"id":68,"title":"Frédéric Malle — Acne Studios par Frédéric Malle","tagline":"Альдегидный · цветочно-мускусный · сливочный","description":"Acne Studios — аромат человека, который надевает простую белую футболку так, словно это вещь из последней коллекции парижского дизайнера.\n\nПредставьте светлую студию в Стокгольме: большие окна, кресло необычной формы, стопка художественных альбомов и мягкий мохеровый свитер, в который хочется завернуться после долгой прогулки. Здесь модно не потому, что дорого, а потому, что у каждой вещи есть характер.\n\nИскристые альдегиды создают ощущение прохладной, почти хрустящей чистоты. Но очень скоро в неё вплетаются роза, фиалка, цветок апельсина и нежный персик. Ваниль, сливочный сандал и белый мускус смягчают композицию, а тонкий ладан добавляет неожиданную глубину.\n\nAcne Studios понравится тем, кто любит запах чистой ткани, но ищет в нём не стерильность, а индивидуальность. Немного странный, очень уютный, современный — как любимая вещь, которую невозможно заменить.","notes":{"top":"Альдегиды, мандарин, бергамот.","middle":"Персик, цветок апельсина, фиалка, роза, ландыш, жасмин.","base":"Мускус, Iso E Super, сандал, ладан, ваниль, гелиотроп.","other":"альдегиды, роза, фиалка, цветок апельсина, персик, ваниль, сандал, ладан, белый мускус."},"brand":"Frédéric Malle","name":"Acne Studios par Frédéric Malle","price3":1200,"price5":2000,"price10":4000,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/068.webp","placeholder":false},{"id":69,"title":"Parfums de Marly — Valaya Eau de Parfum","tagline":"Цитрусовый · белоцветочный · мускусный","description":"Valaya — аромат женщины, которая любит белые рубашки, свежие цветы и то редкое ощущение, когда всё в жизни находится на своём месте.\n\nПредставьте утро в красивом отеле: на кровати белоснежное бельё, на столике — букет цветов, за окном — солнечный сад. Вы только что вышли из душа, на коже ещё остались капли воды, а впереди день, который хочется прожить медленно и с удовольствием.\n\nБергамот, мандарин и белый персик дают сочную, светлую свежесть. В сердце раскрываются цветок апельсина и белые цветы — нежные, воздушные, словно тончайшая ткань. Белый мускус, акигалавуд, ваниль и ветивер добавляют мягкую древесную глубину.\n\nВ Valaya особенно красиво соединяются прохлада и тепло. Она понравится тем, кто любит ухоженные, прозрачные, чистые ароматы с нежным фруктовым оттенком и мягким, обволакивающим шлейфом.","notes":{"top":"бергамот, мандарин, белый персик.","middle":"цветок апельсина, белые цветы.","base":"белый мускус, акигалавуд, ваниль, ветивер.","other":""},"brand":"Parfums de Marly","name":"Valaya EDP","price3":1200,"price5":2000,"price10":4000,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/069.webp","placeholder":false},{"id":70,"title":"ZEZEJ — Arctic Bloom Eau de Parfum","tagline":"Цитрусовый · прохладный · имбирный","description":"Arctic Bloom — аромат свежести, которая действует лучше второй чашки кофе.\n\nПредставьте утро на северном побережье: ветер треплет волосы, в воздухе чувствуется прохлада, а горизонт такой чистый и широкий, что хочется вдохнуть полной грудью. Никакой тяжёлой сладости, только ощущение движения и свободы.\n\nВ композиции заявлены яркие цитрусы и терпкий грейпфрут. Имбирь добавляет бодрящую, чуть колкую пряность, а свежие оттенки поддерживают ощущение прохладного воздуха. В результате получается звонкий, энергичный характер без тяжёлой базы.\n\nArctic Bloom понравится тем, кто выбирает бодрящие, освежающие ароматы и любит чувствовать лёгкость даже в самый насыщенный день.","notes":{"top":"Грейпфрут, цитрусовые.","middle":"Имбирь.","base":"Свежий аккорд.","other":"По данным парфюмерного магазина: цитрусы, грейпфрут, имбирь, свежие ноты."},"brand":"ZEZEJ","name":"Arctic Bloom EDP","price3":600,"price5":1000,"price10":2000,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/070.webp","placeholder":false},{"id":71,"title":"BDK Parfums — Gris Charnel Eau de Parfum","tagline":"Инжирный · чайный · древесно-пудровый","description":"Gris Charnel — аромат свидания, на которое вы собирались всего на час, а вернулись под утро.\n\nПредставьте дождливый Париж. На окнах кафе — капли воды, в чашке остывает чёрный чай, за столиком напротив сидит человек, с которым разговор становится всё интереснее. За окном уже темно, но никто не смотрит на часы.\n\nСочный инжир и терпкий чёрный чай встречаются с пряным кардамоном. Затем появляется пудровый ирис — прохладный, элегантный, немного загадочный. Сандал, ветивер и бобы тонка создают мягкую древесную глубину, похожую на тепло кашемирового пальто.\n\nВ Gris Charnel есть редкая красота полутона: он одновременно уютный и чувственный, спокойный и интригующий. Понравится тем, кто любит интеллектуальную, бархатистую парфюмерию без очевидной сладости.","notes":{"top":"инжир, чёрный чай, эссенция кардамона.","middle":"абсолют ириса, бурбонский ветивер.","base":"индийский сандал, абсолют бобов тонка.","other":""},"brand":"BDK Parfums","name":"Gris Charnel EDP","price3":750,"price5":1250,"price10":2500,"priceFull":null,"available":true,"hit":true,"new":false,"image":"assets/products/071.webp","placeholder":false},{"id":72,"title":"RudRoss — Road to Paradise Eau de Parfum","tagline":"Чайный · цветочно-древесный · молочно-ванильный","description":"Road to Paradise — аромат счастья, у которого нет расписания и адреса.\n\nПредставьте выходной в красивом доме у воды. Вы открываете окно, завариваете белый чай и позволяете себе не думать о делах. На подоконнике стоит ветка цветущего апельсина, а на плечах — мягкий плед. Кажется, что для полного счастья сейчас действительно ничего больше не нужно.\n\nОсмантус привносит тонкую фруктово-цветочную мягкость, белый чай — спокойную прозрачность. Цветок апельсина и сандал делают сердце композиции нежным и сливочным. В базе появляются кашемировое дерево, амбровая древесность, молоко и ваниль: тёплые, гладкие, обволакивающие оттенки.\n\nRoad to Paradise понравится тем, кто любит уютную, деликатно сладкую парфюмерию с красивой древесной основой. Это запах внутреннего комфорта — когда хорошо не потому, что случилось что-то грандиозное, а просто потому, что вы счастливы.","notes":{"top":"османтус, белый чай.","middle":"цветок апельсина, сандал.","base":"кашемировое дерево, амбровая древесина (amberwood), молоко, ваниль.","other":""},"brand":"RudRoss","name":"Road to Paradise EDP","price3":600,"price5":1000,"price10":2000,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/072.webp","placeholder":false},{"id":73,"title":"Zadig & Voltaire — This Is Her! Eau de Parfum","tagline":"Цветочный · сливочно-каштановый · древесный","description":"This Is Her! — аромат девушки, которая может надеть шёлковое платье с грубыми ботинками и выглядеть в этом гораздо интереснее, чем в идеальном вечернем образе.\n\nПредставьте Париж после концерта. На плечах — чужая кожаная куртка, волосы немного растрепались от ветра, в руках бумажный стаканчик горячего кофе. Вы смеётесь, идёте по ночной улице и совсем не думаете о том, как выглядите. Потому что чувствуете себя невероятно красивой.\n\nЖасмин самбак раскрывается ярко и женственно, розовый перец добавляет ему пикантности. Затем приходит главное удовольствие: мягкая ваниль и тёплый каштан, будто сливочный десерт с ореховой начинкой. Сандал собирает всё в уютный, гладкий, древесный шлейф.\n\nЭто аромат нежности с рок-н-ролльным характером. Он понравится тем, кто любит сливочную гурманику, но не хочет пахнуть кондитерской витриной. В нём есть и ласка, и свобода, и лёгкая привычка поступать по-своему.","notes":{"top":"Розовый перец, жасмин самбак, цветок шёлкового дерева.","middle":"Взбитые сливки, ваниль, каштан.","base":"Сандал, кашемировое дерево.","other":"жасмин самбак, ваниль, каштан, розовый перец, сандал."},"brand":"Zadig & Voltaire","name":"This Is Her! EDP","price3":600,"price5":1000,"price10":2000,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/073.webp","placeholder":false},{"id":74,"title":"Initio Parfums Privés — Oud for Greatness Eau de Parfum","tagline":"Удовый · пряный · древесно-мускусный","description":"Oud for Greatness — аромат человека, которому тесно в чужих представлениях о том, каким он должен быть.\n\nПредставьте старинный особняк с высокими дверями и тёмным деревом. В кабинете горит камин, на столе лежит тяжёлая книга, за окном — холодный вечер. Здесь всё говорит о силе, выдержке и безупречном вкусе, но ни одна деталь не кажется случайной.\n\nЛаванда приносит неожиданную прохладу, мускатный орех и шафран — горячую, чуть сухую пряность. В центре звучит насыщенный уд: тёмный, благородный, плотный. Пачули и мускус делают его ещё глубже, добавляя бархатистую, почти гипнотическую теплоту.\n\nOud for Greatness понравится тем, кто любит масштабные восточно-древесные композиции, эффектные фактуры и ароматы с мощным характером. Это не парфюмерная застенчивость — это удовольствие от собственной силы.","notes":{"top":"Шафран, мускатный орех, лаванда.","middle":"Уд (агаровое дерево).","base":"Пачули, мускус.","other":"уд (агаровое дерево), лаванда, шафран, мускатный орех, пачули, мускус."},"brand":"Initio Parfums Privés","name":"Oud for Greatness EDP","price3":1500,"price5":2500,"price10":5000,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/074.webp","placeholder":false},{"id":75,"title":"Les 12 Parfumeurs Français — Malmaison","tagline":"Розовый · смородиновый · зелёно-древесный","description":"Malmaison — аромат прогулки по саду, в котором цветы выращивают не ради красивой фотографии, а ради самого удовольствия жить среди них.\n\nПредставьте французское поместье ранним летом. На гравийной дорожке ещё блестят капли дождя, кусты чёрной смородины тянутся к солнцу, а старинные розы пахнут так насыщенно, будто их лепестки только что растёрли между пальцами. Вдалеке виднеется белая веранда с накрытым к завтраку столом.\n\nРоза здесь не помадная и не сахарная — живая, с зелёными стеблями и влажными лепестками. Чёрная смородина добавляет ягодную терпкость, ветивер — прохладную землистую древесность, а мускус смягчает композицию, словно тонкая вуаль.\n\nMalmaison понравится тем, кто любит натуральное звучание цветов, зелёную свежесть и атмосферу старых европейских садов. В нём есть аристократическая романтика, но без театральной пышности.","notes":{"top":"Роза.","middle":"Чёрная смородина.","base":"Ветивер, мускус.","other":"Подтверждённые профильными источниками ноты: роза, чёрная смородина, ветивер, мускус."},"brand":"Les 12 Parfumeurs Français","name":"Malmaison","price3":900,"price5":1500,"price10":3000,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/075.webp","placeholder":false},{"id":76,"title":"Bottega Veneta — Balliamo Eau de Parfum","tagline":"Цитрусовый · инжирный · древесно-ароматический","description":"Balliamo — аромат итальянского лета, в котором у вас наконец-то нет расписания.\n\nПредставьте вечер на побережье. Столик на маленькой площади, белая скатерть, бокалы звенят от смеха, кто-то включает музыку, и через минуту вы уже танцуете прямо между столиками. Сандалии в руках, волосы пахнут морским воздухом, а жизнь кажется восхитительно простой.\n\nПомело и цитрон дают яркую, чуть горьковатую цитрусовую свежесть, перец добавляет живую искру. Затем появляется зелёный, молочно-сочный белый инжир, окружённый миртом и лавандой. Кедр, ветивер и амброво-древесный аккорд делают шлейф сухим, благородным и удивительно притягательным.\n\nBalliamo понравится тем, кто любит инжир не в виде сладкого варенья, а как запах листьев, тёплой кожи и средиземноморского воздуха. Свободный, элегантный и немного беспечный — как лучший отпуск.","notes":{"top":"помело, цитрон, свежий перец.","middle":"мирт, абсолют лаванды, аккорд белого инжира Vitessence®.","base":"кедр, ветивер, Ambronova.","other":""},"brand":"Bottega Veneta","name":"Balliamo EDP","price3":2100,"price5":3500,"price10":7000,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/076.webp","placeholder":false},{"id":77,"title":"Bottega Veneta — Bare Morning Eau de Parfum","tagline":"Пудровый · абрикосовый · мускусно-сандаловый","description":"Bare Morning — аромат утра, которое хочется прожить медленно, не проверяя телефон и не торопясь становиться взрослым серьёзным человеком.\n\nПредставьте просторную спальню, залитую мягким солнцем. Белые простыни немного смяты, на тумбочке лежит раскрытая книга, на коже ещё ощущается тепло сна. За окном уже шумит город, но у вас есть несколько драгоценных минут, когда весь мир может подождать.\n\nРозовый перец слегка щекочет прохладой, косточка абрикоса даёт нежную фруктово-ореховую мягкость. Фрезия приносит прозрачную цветочную свежесть, а итальянский пудровый аккорд напоминает о чистой, ухоженной коже. Сандал, кашмеран и щедрая порция мускуса делают аромат сливочным, телесным и невероятно уютным.\n\nBare Morning понравится тем, кто ищет не громкую парфюмерную историю, а ощущение близости: мягкий кашемир, тёплое плечо рядом, свежие простыни и нежность, которой не нужны объяснения.","notes":{"top":"CO₂-экстракт розового перца, эссенция абрикосовой косточки.","middle":"итальянский пудровый аккорд Borotalco, аккорд фрезии.","base":"эссенция сандала, усиленный аккорд кожных мускусов, Cashmeran®.","other":""},"brand":"Bottega Veneta","name":"Bare Morning EDP","price3":2100,"price5":3500,"price10":7000,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/077.webp","placeholder":false},{"id":78,"title":"CELINE — Parade Eau de Parfum","tagline":"Цитрусовый · пудровый · древесно-мускусный","description":"Parade — аромат человека, которому удивительно идёт свобода быть собой. В нём есть французская небрежность, но каждая её деталь продумана.\n\nПредставьте Париж ранним утром: старое зеркало в номере, белоснежная рубашка, слегка растрёпанные волосы и кофе, который успевают выпить только наполовину. Впереди прогулка без маршрута, антикварные лавки и случайная встреча, способная изменить планы на весь день.\n\nБергамот и нероли дают светлую цитрусовую свежесть, будто солнце коснулось нагретого камня. Ветивер добавляет сухую, благородную древесность, дубовый мох — лёгкую винтажную строгость. Мускус окутывает всё мягкой пудровой дымкой, напоминающей чистую кожу и дорогую ткань.\n\nParade понравится тем, кто любит интеллектуальную свежесть без спортивной резкости. Это аромат для поклонников хорошего кроя, старого кино и вещей, которые с годами становятся только красивее.","notes":{"top":"Бергамот.","middle":"Нероли.","base":"Ветивер, дубовый мох, мускус.","other":"бергамот, нероли, ветивер, мускус, дубовый мох. Полную пирамиду бренд не разделяет."},"brand":"CELINE","name":"Parade EDP","price3":1800,"price5":3000,"price10":6000,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/078.webp","placeholder":false},{"id":79,"title":"CELINE — Black Tie Eau de Parfum","tagline":"Ванильный · пудровый · древесный","description":"Black Tie — ваниль, у которой безупречные манеры и собственное мнение. Она не напоминает кондитерскую: скорее дорогой чёрный смокинг, надетый на голое тело.\n\nПредставьте вечер в старинном особняке. Приглушённый свет, тяжёлые шторы, бокал шампанского. Вы выбираете чёрный наряд, гладкую причёску и украшение, которое не требует объяснений. В этом образе нет ничего лишнего — только великолепная фактура.\n\nВаниль здесь плотная, гладкая, почти лакированная. Ирис придаёт ей сухую косметическую пудровость, кедр выстраивает строгий древесный силуэт, древесный мох добавляет тёмную глубину. Мускус смягчает композицию, оставляя ощущение тёплой кожи под прохладной тканью.\n\nBlack Tie понравится тем, кто ищет не десертную сладость, а взрослую, собранную, чувственную ваниль. Особенно красив для вечерних выходов, когда хочется выглядеть безупречно, но сохранить немного тайны.","notes":{"top":"Масло белого ириса, бурбонская ваниль.","middle":"Кедр.","base":"Древесный мох, чистый мускус.","other":"масло белого ириса, кедр, древесный мох, ваниль, мускус. Бренд не публикует трёхступенчатую пирамиду."},"brand":"CELINE","name":"Black Tie EDP","price3":1800,"price5":3000,"price10":6000,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/079.webp","placeholder":false},{"id":80,"title":"Chloé Atelier des Fleurs — Vert Soleil Eau de Parfum","tagline":"Зелёный · цитрусовый · древесно-мускусный","description":"Vert Soleil — аромат лета, в котором нет ни одной лишней минуты. Только солнце, зелень, море и ощущение, что счастье наконец-то стало очень простым.\n\nПредставьте утро на юге Франции. Терраса утопает в листве, на столе лежат свежие мандарины, из сада доносится стрёкот цикад. Вы идёте босиком по прохладной плитке, открываете окна и впускаете в дом весь средиземноморский воздух.\n\nЗелёный мандарин звучит сочно и звонко, а мастиковое дерево добавляет необычную смолистую, чуть терпкую зелень. Мягкая древесная основа и мускус согревают композицию, будто солнечные лучи постепенно высушивают капли воды на коже.\n\nVert Soleil понравится тем, кто любит естественную, живую свежесть: не стерильную чистоту, а аромат листьев, цитрусовой кожуры и тёплого воздуха. Особенно прекрасен в жару и в дни, когда хочется мысленно уехать к морю.","notes":{"top":"Зелёный мандарин, бергамот, мята.","middle":"Герань, розовый перец, мастика (лентиск).","base":"Чёрный перец, Ambrofix, Petalia.","other":"зелёный мандарин, мастиковое дерево (мастика), мускус, древесные ноты. Полная пирамида брендом не заявлена."},"brand":"Chloé Atelier des Fleurs","name":"Vert Soleil EDP","price3":1200,"price5":2000,"price10":4000,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/080.webp","placeholder":false},{"id":81,"title":"Balenciaga — Amber Crush Extrait de Parfum","tagline":"Амбровый · сливово-ликёрный · смолисто-пряный","description":"Amber Crush — аромат роскоши с опасно красивым характером. Густой, чувственный, почти осязаемый, как тёмный бархат, который хочется провести между пальцами.\n\nПредставьте закрытый ужин в современном особняке. На столе — хрусталь, за панорамными окнами мерцает ночной город. В бокале густой сливовый ликёр, на коже — тепло дорогих украшений. Вечер ещё только начинается, но атмосфера уже полна предвкушения.\n\nСочная слива здесь звучит не как свежий фрукт, а как насыщенный ликёр — тёмный, сладковато-терпкий. Её обволакивают пряные смолы и тёплая амбра, а сандал добавляет сливочную древесную мягкость. Композиция постепенно становится глубже, плотнее, соблазнительнее.\n\nAmber Crush понравится тем, кто любит насыщенные амбровые ароматы с фруктовой роскошью и бархатистой древесной базой. Для вечеров, когда хочется не лёгкости, а настоящего удовольствия от каждой детали.","notes":{"top":"Мускатный орех, сливовый аккорд, шафран.","middle":"Олибанум (ладан), смолисто-амбровый аккорд.","base":"Абсолют ванили, пачули, австралийский сандал.","other":"амбра, смолистые и пряные ноты, аккорд сочного сливового ликёра, сандал. Полная пирамида не опубликована."},"brand":"Balenciaga","name":"Amber Crush","price3":2400,"price5":4000,"price10":8000,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/081.webp","placeholder":false},{"id":82,"title":"FENDI — Sempre Mio Eau de Parfum","tagline":"Цитрусовый · цветочный · древесный","description":"Sempre Mio — аромат воспоминаний, которые остаются с нами навсегда. Не потому, что они были безупречными, а потому, что в них было настоящее счастье.\n\nПредставьте Марракеш в конце весны. Во внутреннем дворике старого дома цветёт апельсиновое дерево. На столе — холодный лимонад, за стенами слышны голоса, а над крышами дрожит тёплый воздух. Вы приехали ненадолго, но почему-то чувствуете себя дома.\n\nКалабрийский бергамот открывает композицию светлой искристой свежестью. Марокканский флердоранж звучит солнечно, чуть медово и одновременно прохладно, словно белые цветы после полива. Атласский кедр добавляет сухую древесную теплоту и спокойную, уверенную глубину.\n\nSempre Mio понравится тем, кто любит ароматы с душой: свежие, но согретые солнцем; цветочные, но с характером. В нём есть и итальянская элегантность, и марокканская чувственность — история, которую хочется носить близко к коже.","notes":{"top":"Калабрийский бергамот.","middle":"Абсолют марокканского цветка апельсина.","base":"Атласский кедр.","other":"цельный калабрийский бергамот, абсолют марокканского цветка апельсина, марокканский атласский кедр. Бренд не приводит полную трёхступенчатую пирамиду."},"brand":"FENDI","name":"Sempre Mio EDP","price3":2100,"price5":3500,"price10":7000,"priceFull":null,"available":true,"hit":true,"new":false,"image":"assets/products/082.webp","placeholder":false},{"id":83,"title":"Louis Vuitton — Attrape-Rêves Eau de Parfum","tagline":"Цветочно-фруктовый · какао · сияющий","description":"Attrape-Rêves — аромат женщины, которая умеет мечтать с размахом и получать удовольствие от самого пути к желаемому.\n\nПредставьте вечер на крыше парижского отеля. Город мерцает огнями, в бокале искрится шампанское, а в воздухе есть то особенное предчувствие, когда кажется: сегодня может случиться всё. Вы нарядились не ради чужих взглядов — просто вам нравится собственная жизнь.\n\nСочная, почти прозрачная личи придаёт композиции искристую фруктовую свежесть. Пион раскрывается нежно и воздушно, а какао неожиданно добавляет бархатистую, слегка горьковатую глубину. Пачули связывает эти контрасты и делает шлейф более выразительным.\n\nЭто не шоколадный десерт и не привычный цветочный букет. Attrape-Rêves напоминает красивую мечту, в которой есть и лёгкость, и азарт, и немного взрослой чувственности. Для тех, кто любит женственные ароматы с необычным характером.","notes":{"top":"Личи, имбирь, бергамот.","middle":"Турецкая роза, пион, какао.","base":"Пачули.","other":"Ключевые ноты производителя: какао, аккорд пиона, аккорд личи."},"brand":"Louis Vuitton","name":"Attrape-Rêves EDP","price3":2100,"price5":3500,"price10":7000,"priceFull":null,"available":true,"hit":false,"new":true,"image":"assets/products/083.webp","placeholder":false},{"id":84,"title":"Bottega Veneta — Always Now Eau de Parfum","tagline":"Цитрусовый · зелёный · ветиверовый","description":"Always Now — аромат женщины, которая умеет получать удовольствие от настоящего момента. От солнечного света на стене, от первого глотка эспрессо, от внезапного решения провести выходные у моря.\n\nПредставьте утро в Милане. На вас идеально сидит белая рубашка, в руках бумажный пакет с тёплой выпечкой, впереди — день без строгого расписания. В маленьком кафе на подоконнике растёт базилик, и его терпкий зелёный запах смешивается с цитрусами.\n\nБазилик, лимон, бергамот, зелёный мандарин и клементин дают бодрое, сочное начало; имбирь добавляет лёгкую остроту. В сердце появляются прохладная мята, нероли и петитгрейн. Затем композиция становится суше и благороднее благодаря ветиверу, кедру и мускусу.\n\nAlways Now понравится тем, кто любит свежесть не стерильную, а живую: с ароматом зелени, солнца, красивой древесины и хорошего настроения. Это элегантность, которой очень идёт непринуждённость.","notes":{"top":"базилик, бергамот, лимон, зелёный мандарин, сладкий апельсин, свежий имбирь, клементин.","middle":"петитгрейн, мята колосистая, нероли, Figolide.","base":"бурбонский ветивер с Мадагаскара, виргинский кедр, мускусы.","other":""},"brand":"Bottega Veneta","name":"Always Now EDP","price3":2100,"price5":3500,"price10":7000,"priceFull":null,"available":true,"hit":false,"new":true,"image":"assets/products/084.webp","placeholder":false},{"id":85,"title":"Fendi — Sogni d’Oro Eau de Parfum","tagline":"Кожаный · пудрово-ирисовый · цитрусовый","description":"Sogni d’Oro — аромат человека, который ценит красоту вещей с историей. В нём итальянская элегантность встречается с теплом любимой кожаной куртки и мягкой, почти невесомой пудрой ириса.\n\nПредставьте Рим в золотой час. Солнце ложится на старинные фасады медовым светом, в витринах отражаются узкие улицы, а в воздухе чувствуется прохлада наступающего вечера. На ком-то идеально сидит кожаный жакет, на ком-то — мягкое кашемировое пальто. Здесь важен не образ мужчины или женщины, а особое чувство собственного стиля.\n\nИтальянский бергамот добавляет светлую, искристую свежесть. Французский ирис раскрывается тонкой бархатистой пудрой — благородной, суховатой, словно дорогая замша. Кожаный аккорд придаёт композиции глубину, теплоту и красивую строгость. В этом сочетании есть одновременно сила и нежность.\n\nSogni d’Oro одинаково органично раскрывается в мужском и женском парфюмерном гардеробе. Он понравится тем, кто любит интеллектуальные кожано-ирисовые композиции, необычную фактуру и сдержанную, очень личную чувственность.","notes":{"top":"Итальянский бергамот.","middle":"Французский ирис.","base":"Кожаный аккорд.","other":"кожаный аккорд, французский ирис, итальянский бергамот."},"brand":"FENDI","name":"Sogni d’Oro EDP","price3":2100,"price5":3500,"price10":7000,"priceFull":null,"available":true,"hit":false,"new":true,"image":"assets/products/085.webp","placeholder":false},{"id":86,"title":"Oman Luxury — Wanderlust Eau de Parfum","tagline":"Чёрносмородиновый · зелёный · цитрусово-пряный","description":"Wanderlust — аромат, в котором чёрная смородина звучит так ярко, будто вы раздавили между пальцами целую горсть спелых ягод вместе с листьями.\n\nПредставьте летнее утро за городом. Сад ещё прохладный после ночи, на кустах темнеет смородина, а вы срываете ягоды прямо с ветки. В воздухе смешиваются терпкая зелень, кисловатый ягодный сок и свежесть цитрусов. Именно это сочное, живое ощущение делает Wanderlust таким запоминающимся.\n\nБергамот и лимон добавляют искристую свежесть, розовый перец — лёгкую пикантность. Но главная героиня композиции — чёрная смородина: насыщенная, кисло-сладкая, с характерной зелёной терпкостью. Корица и шафран согревают её пряным оттенком, а кедр, гваяковое дерево и ладан придают аромату благородную древесную глубину. Получается необычный контраст: яркая ягода и строгая, чуть дымная база.\n\nWanderlust понравится тем, кто обожает смородиновые ароматы, но ищет не ягодный сироп, а свежую, терпкую, выразительную композицию с зеленью и древесиной. Это унисекс: на одной коже он может подчеркнуть сочную фруктовость, на другой — пряную, древесную сторону.","notes":{"top":"Лимон, бергамот, розовый перец.","middle":"Чёрная смородина, шафран, корица.","base":"Гваяковое дерево, кедр, олибанум (ладан).","other":"Пирамида Oman Luxury Wanderlust (классическая версия): верхние ноты — бергамот, лимон, розовый перец; ноты сердца — чёрная смородина, корица, шафран; базовые ноты — гваяковое дерево, кедр, ладан."},"brand":"Oman Luxury","name":"Wanderlust EDP","price3":1050,"price5":1750,"price10":3500,"priceFull":null,"available":true,"hit":false,"new":true,"image":"assets/products/086.webp","placeholder":false},{"id":87,"title":"Xerjoff Casamorati — Tempio d’Acqua Eau de Parfum","tagline":"Персиковый · цветочный · смолисто-ванильный","description":"Tempio d’Acqua — аромат отдыха, который начинается ещё до того, как вы успели распаковать чемодан.\n\nПредставьте старинный итальянский термальный курорт. Цветные витражи отбрасывают солнечные блики на мрамор, за окнами зеленеют холмы, в воздухе чувствуется влажная прохлада и аромат спелых фруктов. Здесь даже тишина кажется роскошной.\n\nСочный персик встречается с мандарином и бергамотом — начало нежное, солнечное, почти бархатистое. В сердце появляются фенхель, цистус и воздушный цветочный аккорд Mahonial. Ваниль смягчает композицию, а мирра добавляет ей тонкую смолистую, чуть дымную глубину.\n\nTempio d’Acqua понравится тем, кто любит фруктовые ароматы с неожиданным развитием. Он не превращается в обычную сладость: в нём есть травяная прохлада, мягкая дымка и красивое ощущение умиротворения.","notes":{"top":"бергамот, персик, мандарин.","middle":"масло цистуса, фенхель, Mahonial.","base":"ваниль, мирра.","other":""},"brand":"Xerjoff Casamorati","name":"Tempio d’Acqua EDP","price3":1200,"price5":2000,"price10":4000,"priceFull":null,"available":true,"hit":false,"new":true,"image":"assets/products/087.webp","placeholder":false},{"id":88,"title":"Laurent Mazzone Parfums — Dulce Pear","tagline":"Фруктовый · пудровый · карамельно-древесный","description":"Есть ароматы, которые напоминают о лете. А Dulce Pear пахнет тем самым летом, когда вы ни разу не посмотрели на часы.\n\nПредставьте маленький итальянский городок. На рынке продают груши с тонкой золотистой кожицей, в кафе звенят чашки, а вы выбираете самый спелый фрукт и откусываете его прямо на улице. Сладкий сок, тёплое солнце и ощущение, что сегодня можно позволить себе всё — хотя бы никуда не торопиться.\n\nЗдесь груша сочная, мягкая, почти медовая. Зелёное яблоко придаёт ей звонкую свежесть, ирис и амбретта обволакивают фрукт нежной пудровой дымкой. Кедр и коричневый сахар оставляют тёплый, чуть карамельный след — словно на пальцах осталась сладость после десерта.\n\nDulce Pear понравится тем, кто ищет красивую фруктовую гурманику без тяжёлого сиропа: жизнерадостную, нежную, очень аппетитную и при этом изящную.","notes":{"top":"груша, зелёное яблоко.","middle":"ирис, амбретта.","base":"кедр, коричневый сахар.","other":"Розничная стоимость"},"brand":"Laurent Mazzone Parfums","name":"Dulce Pear","price3":600,"price5":1000,"price10":2000,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/088.webp","placeholder":false},{"id":89,"title":"Laurent Mazzone Parfums — Aldhèyx","tagline":"Альдегидный · пудровый · мускусно-древесный","description":"Aldhèyx — аромат идеально выглаженной белой рубашки, на которую кто-то оставил едва заметный след дорогой пудры.\n\nПредставьте утро в старом парижском отеле. В ванной комнате большое зеркало, на мраморной полке лежит серебряная пудреница, а из открытого окна тянет прохладой. Вы собираетесь без спешки: свежая кожа, чистые волосы, безупречная ткань. Никаких лишних украшений — всё внимание к деталям.\n\nСвежие альдегиды и бергамот создают сверкающую, почти хрустальную чистоту. Жасмин смягчает её, а гелиотроп добавляет бархатистую пудровость. Кашмеран и белый мускус делают аромат телесным, тёплым и невероятно ухоженным.\n\nAldhèyx понравится тем, кто любит интеллигентные, чистые, пудровые ароматы. Он красив и на строгом костюме, и на мягком трикотаже — независимо от того, кто его носит.","notes":{"top":"свежие альдегиды, бергамот.","middle":"лепестки жасмина, гелиотроп.","base":"кашмеран, белый мускус.","other":"Розничная стоимость"},"brand":"Laurent Mazzone Parfums","name":"Aldhèyx","price3":600,"price5":1000,"price10":2000,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/089.webp","placeholder":false},{"id":90,"title":"What We Do Is Secret — Messy Sexy Just Rolled Out of Bed","tagline":"Мускусный · цветочно-гурманский · нежно-ванильный","description":"Messy Sexy Just Rolled Out of Bed — аромат той близости, для которой не нужны ни идеальная причёска, ни красивое платье.\n\nПредставьте позднее воскресное утро. Солнечный свет полосами ложится на смятые простыни, на кухне уже пахнет кофе, но вставать совершенно не хочется. Кто-то обнимает вас со спины, и весь мир на несколько минут становится удивительно маленьким и счастливым.\n\nЦветок персика и бергамот создают мягкое, светлое начало. Турецкая роза и гелиотроп добавляют нежную, чуть миндальную пудровость. Затем появляются мускус, тёплая амбра, карамельный ирисковый оттенок, ваниль, бобы тонка и светлая древесина. Получается запах тёплой кожи и сладости, которую хочется почувствовать совсем близко.\n\nЭто аромат для любителей деликатной, чувственной гурманики — не кондитерской витрины, а нежности после долгого поцелуя. Одинаково органично звучит на женской и мужской коже.","notes":{"top":"цветок персика, бергамот.","middle":"турецкая роза, аккорд гелиотропа.","base":"мускус, ириска тоффи, амбра, светлая древесина, ваниль, абсолют бобов тонка.","other":"Розничная стоимость"},"brand":"What We Do Is Secret","name":"Messy Sexy Just Rolled Out of Bed","price3":1050,"price5":1750,"price10":3500,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/090.webp","placeholder":false},{"id":91,"title":"Tom Ford — Soleil Neige Eau de Parfum","tagline":"Цитрусовый · белоцветочный · мускусно-амбровый","description":"Soleil Neige — аромат солнца, отражённого от свежего снега. Холодного на вид и неожиданно тёплого на коже.\n\nПредставьте утро в Альпах. За панорамным окном сверкают белые склоны, на кресле ждёт мягкий кремовый свитер, а на столе — бокал игристого после прогулки. Воздух прозрачный, щёки розовые от мороза, и даже обычный день кажется маленьким праздником.\n\nБергамот даёт яркую, чистую цитрусовую вспышку. Цветок апельсина и жасмин создают сияющий белоцветочный букет. Затем проявляются бархатистый мускус, бензоин и лабданум — мягкое амбровое тепло, будто солнце постепенно согревает кожу после морозного воздуха.\n\nSoleil Neige понравится тем, кто любит свежие, светлые, дорогие по ощущению композиции без навязчивой сладости. Идеальный контраст: ледяная прозрачность и нежное тепло.","notes":{"top":"Бергамот, семена моркови.","middle":"Жасмин грандифлорум, цветок апельсина.","base":"Лабданум, бензоин, мускус.","other":"Ключевые ноты, заявленные Tom Ford: бергамот, мускусные ноты, цветок апельсина, жасмин грандифлорум, бензоин, лабданум."},"brand":"Tom Ford","name":"Soleil Neige EDP","price3":1050,"price5":1750,"price10":3500,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/091.webp","placeholder":false},{"id":92,"title":"Philly & Phill — Easy for Ecstasy Eau de Parfum","tagline":"Чистый мускус · амбра · кедровая древесина","description":"Easy for Ecstasy — аромат, который напоминает о моменте, когда между двумя людьми уже всё понятно, хотя они ещё ничего не сказали.\n\nПредставьте поздний вечер после долгого разговора. За окном стих город, на диване лежит плед, а вы сидите совсем рядом. Больше не нужно производить впечатление. Можно просто быть собой — и почему-то именно сейчас хочется подвинуться ещё ближе.\n\nБелый мускус звучит чисто, прозрачно и почти невесомо. Амбра добавляет мягкое тепло, кедр — сухую, аккуратную древесную линию. В базе остаётся нежный мускусный след, похожий на запах свежей кожи после душа.\n\nEasy for Ecstasy понравится тем, кто любит спокойные, интимные ароматы без тяжёлых цветов и сладких десертов. Он про доверие, комфорт и притяжение, которое ощущается на расстоянии одного прикосновения.","notes":{"top":"белый мускус.","middle":"амбра, кедр.","base":"мускус.","other":"Розничная стоимость"},"brand":"Philly & Phill","name":"Easy for Ecstasy EDP","price3":450,"price5":750,"price10":1500,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/092.webp","placeholder":false},{"id":93,"title":"Philly & Phill — Faith for Fantasy Eau de Parfum","tagline":"Гурманский · амбровый · древесно-мускусный","description":"Faith for Fantasy — аромат мечты, которую вы перестали откладывать на потом. Он напоминает о том приятном моменте, когда вы вдруг разрешаете себе больше: красивую поездку, долгожданную покупку, встречу, на которую раньше не хватало смелости.\n\nПредставьте поздний вечер в незнакомом городе. За окном мерцают огни, на столике лежат шоколадные конфеты, а впереди — целая ночь без привычного расписания. В воздухе чувствуется сладость карамели и пралине, но она не кондитерская, а тёплая, обволакивающая, почти бархатная.\n\nВ сердце появляются благородный сандал и амбровые оттенки. Затем мускус, амброксан и древесные ноты придают композиции гладкость и чувственную глубину. Сладость здесь не детская — она похожа на удовольствие от собственной свободы.\n\nFaith for Fantasy понравится тем, кто любит мягкую гурманику, кремовую древесность и уютные ароматы с характером. Он одинаково органично звучит в женском и мужском парфюмерном гардеробе.","notes":{"top":"карамель, пралине.","middle":"амбра (ambergris), сандал.","base":"амброксан, мускус, благородная древесина.","other":""},"brand":"Philly & Phill","name":"Faith for Fantasy EDP","price3":600,"price5":1000,"price10":2000,"priceFull":null,"available":true,"hit":false,"new":true,"image":"assets/products/093.webp","placeholder":false},{"id":94,"title":"Hermès — Terre d’Hermès Eau de Parfum Intense","tagline":"Минеральный · пряно-древесный · тёплый","description":"Terre d’Hermès Eau de Parfum Intense — аромат человека, который не боится сильных решений. В нём чувствуется характер: спокойный снаружи и удивительно горячий внутри.\n\nПредставьте путешествие по вулканическому острову. Под ногами — тёмный камень, нагретый солнцем, вдали виднеется море, а ветер приносит запах сухой земли и древесины. В руках крепкий кофе, впереди крутая дорога, и именно это делает день интересным.\n\nЯркий бергамот даёт цитрусовую искру, но почти сразу композиция становится глубже. Здесь чувствуется необычная минеральность лавового камня, обожжённая древесина, тёплые кофейные и лакричные оттенки. Получается сухое, насыщенное, выразительное звучание без привычной парфюмерной сладости.\n\nАромат понравится любителям интеллектуальной древесной парфюмерии, пряных контрастов и ощущения настоящей силы — без показной суровости.","notes":{"top":"Бергамот, чёрный перец.","middle":"Лакрица, кофе.","base":"Древесные ноты, минеральный аккорд лавового камня.","other":"Официально выделенные ноты и аккорды: бергамот, лавовый камень (минеральный аккорд), обожжённая древесина, кофейные и лакричные оттенки."},"brand":"Hermès","name":"Terre d’Hermès EDP Intense","price3":450,"price5":750,"price10":1500,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/094.webp","placeholder":false},{"id":95,"title":"Gucci The Alchemist’s Garden — Tears from the Moon Eau de Parfum","tagline":"Росистый · цветочный · нежно-мускусный","description":"Tears from the Moon — «Слёзы с Луны». Кажется, само название придумано для аромата, в котором хрупкость становится самой красивой формой нежности.\n\nПредставьте ночное небо, такое светлое, будто Луна наклонилась к Земле совсем близко. С её края срываются прозрачные капли и падают на лепестки белых цветов. Это не слёзы отчаяния. Скорее, слёзы от переполняющих чувств — когда сердце становится таким нежным, что даже счастье хочется проживать тихо.\n\nБелый пион звучит тонко и невесомо, словно лепесток, который страшно помять пальцами. Ландыш добавляет прохладную, росистую свежесть, а стефанотис — деликатную белоцветочную мягкость. В этом аромате словно нет ничего тяжёлого: только влажные цветы, лунный свет и прозрачная красота мгновения.\n\nTears from the Moon понравится тем, кто любит утончённые, трогательные, почти невесомые цветочные ароматы. Тем, кто умеет замечать красоту в самом хрупком: в капле росы, дрожащем лепестке и чувствах, которые не обязательно произносить вслух.","notes":{"top":"Белый пион.","middle":"Ландыш.","base":"Стефанотис (мадагаскарский жасмин).","other":"белый пион, ландыш, стефанотис (мадагаскарский жасмин)."},"brand":"Gucci The Alchemist’s Garden","name":"Tears from the Moon EDP","price3":1500,"price5":2500,"price10":5000,"priceFull":null,"available":true,"hit":false,"new":true,"image":"assets/products/095.webp","placeholder":false},{"id":96,"title":"Chambre52 — Cuir à Corps Eau de Parfum","tagline":"Кожаный · пряный · телесный","description":"Cuir à Corps — аромат близости, у которой есть свой язык. Здесь не нужны красивые обещания: всё решают прикосновения, паузы и то, как пахнет кожа человека рядом.\n\nПредставьте маленький бар после полуночи. Музыка стала тише, на столе остались два бокала, а расстояние между собеседниками незаметно сократилось. В воздухе — тёплая кожа, немного пряностей и мягкая древесная глубина.\n\nРозовый перец даёт пикантное, искрящееся начало. Пачули добавляют землистую, бархатистую насыщенность, а кожаный аккорд постепенно становится мягче и теплее. Парфюмер рассказывает о вдохновении мадагаскарской ванилью, замшей и чувственными мускусами — именно поэтому кожа здесь не грубая, а почти осязаемая.\n\nCuir à Corps понравится тем, кто любит кожаные ароматы с интимным, пряным характером. Это не аксессуар для делового костюма, а настроение для вечера, который хочется продлить.","notes":{"top":"Мандарин, розовый перец, корица.","middle":"Ваниль, цветок апельсина, пачули.","base":"Кожаный аккорд, анималистический аккорд, бензоин.","other":"Официальные ключевые ноты: розовый перец, пачули, кожа."},"brand":"Chambre52","name":"Cuir à Corps EDP","price3":600,"price5":1000,"price10":2000,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/096.webp","placeholder":false},{"id":97,"title":"Electimuss — Amber Bloom Pure Parfum","tagline":"Цитрусовый · фруктовый · солоновато-амбровый","description":"Amber Bloom — аромат солнца, которое остаётся на коже даже после заката. Он сочный, яркий, почти праздничный — но с красивой солоноватой прохладой, которая не даёт фруктам стать слишком сладкими.\n\nПредставьте средиземноморский сад в золотой час. На деревьях зреют цитрусы, с моря тянет солёным ветром, а вы только что вышли из бассейна и накинули на плечи лёгкую рубашку. Кожа ещё тёплая, воздух свежий, настроение беззаботное.\n\nЛимон, грейпфрут, мандарин и бергамот вспыхивают сочной, искристой свежестью. В сердце появляется яркая маракуйя, нежная малина, ландыш и неожиданная морская соль. Амбра, бобы тонка и мускус делают финал гладким, тёплым, чуть сливочным — словно последние лучи солнца.\n\nAmber Bloom понравится любителям выразительных фруктовых ароматов, которым хочется не сиропной сладости, а свежести, движения и красивого тёплого шлейфа.","notes":{"top":"лимон, грейпфрут, мандарин, бергамот.","middle":"ландыш, солёный аккорд, малина, маракуйя.","base":"амбра (ambergris), бобы тонка, мускус.","other":""},"brand":"Electimuss","name":"Amber Bloom","price3":1200,"price5":2000,"price10":4000,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/097.webp","placeholder":false},{"id":98,"title":"Electimuss — Trajan Pure Parfum / Extrait","tagline":"Цитрусовый · шафрановый · амбровый · карамельные оттенки","description":"Trajan — аромат женщины, в которой нежность удивительным образом сочетается с императорским характером.\n\nСвоё название он получил в честь римского императора Траяна, при котором империя достигла наибольших территориальных размеров. Его эпоха стала временем богатства, процветания и расширения торговых связей с Востоком.\n\nИменно это путешествие — от солнечного Средиземноморья к восточным пряностям и драгоценным благовониям — вдохновило создателей аромата.\n\nНо я бы описала Trajan совсем другими образами.\n\nПредставьте женщину в роскошном шёлковом платье цвета шампанского. На её коже — тёплый, золотистый аромат, в котором сочные красные апельсины и мандарины словно покрыты тончайшей глазурью из расплавленного сахара.\n\nЗдесь есть удивительный запах жжёного сахара — горячего, янтарного, с лёгкой карамельной горчинкой. Он напоминает прозрачные леденцы-петушки, которые только что вынули из формочек: сладкие, хрупкие, сверкающие на солнце.\n\nШафран придаёт этой сладости особую роскошь, а амбровые и древесные оттенки делают её объёмной, чувственной, почти гипнотической.\n\nПо настроению Trajan может напомнить Baccarat Rouge 540 — той же золотистой, шафраново-сахарной теплотой и узнаваемой притягательностью. Но здесь больше цитрусовой сочности, света и пряной свежести.\n\nЭто аромат женщины с сильным характером и безупречным вкусом. Она любит красивые вещи, умеет получать удовольствие от жизни и совершенно не собирается отказывать себе в маленьких слабостях.\n\nTrajan понравится тем, кто любит Baccarat Rouge 540, выразительные шафраново-амбровые композиции и необычную сладость с оттенками карамелизированного сахара.\n\nЖжёный сахар, карамель и леденцы — ассоциации со звучанием композиции, а не отдельные заявленные ноты. Официально Trajan позиционируется как унисекс.","notes":{"top":"мандарин, лимон, бергамот, красный апельсин.","middle":"лаванда, шалфей, шафран.","base":"кедр, дубовый мох, амбра (ambergris).","other":""},"brand":"Electimuss","name":"Trajan / Extrait","price3":900,"price5":1500,"price10":3000,"priceFull":null,"available":true,"hit":false,"new":true,"image":"assets/products/098.webp","placeholder":false},{"id":99,"title":"Prada Olfactories — Purple Rain Eau de Parfum","tagline":"Зелёный · ирисовый · древесно-землистый","description":"Purple Rain — аромат дождя, который мог бы идти только в воображении художника: фиолетового, прохладного, превращающего обычный сад в совершенно незнакомое место.\n\nПредставьте, что вы оказались в старинной оранжерее сразу после грозы. Листья блестят от воды, влажная земля пахнет особенно глубоко, а среди густой зелени распускается огромный ирис. Его лепестки кажутся бархатными, почти нереальными.\n\nГальбанум создаёт резкую, звонкую зелень — свежую, с благородной горчинкой. Затем раскрывается ирис: пудровый, прохладный, элегантный. Ветивер добавляет корневую, чуть влажную древесность и ощущение земли после дождя.\n\nPurple Rain понравится тем, кто любит парфюмерию не за сладость, а за необычную красоту. Это аромат для человека с собственным взглядом на мир, которому интереснее искусство, чем предсказуемые комплименты.","notes":{"top":"Гальбанум, бергамот.","middle":"Ирис, нероли, гедион, роза.","base":"Фиалка, белый мускус, ветивер, Iso E Super, кедр, сандал.","other":"гальбанум, ирис, ветивер."},"brand":"Prada Olfactories","name":"Purple Rain EDP","price3":900,"price5":1500,"price10":3000,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/099.webp","placeholder":false},{"id":100,"title":"AMEHA Paris — Poire Émeraude Extrait de Parfum","tagline":"Грушевый · фруктово-карамельный · ванильный","description":"Poire Émeraude — аромат сочной груши, которую будто превратили в драгоценный камень. Только этот изумруд хочется не надеть, а попробовать на вкус.\n\nПредставьте красивую кондитерскую в Париже. На витрине — прозрачные фруктовые десерты, тонкие ломтики груши, тёмная вишня и карамель с золотистыми бликами. Вы выбираете самый необычный и уже предвкушаете первое сладкое мгновение.\n\nГруша здесь спелая, сочная, хрустящая; бергамот добавляет свежести, а вишня — яркий ягодный оттенок. Затем появляется мягкий миндаль и тёплая карамель. Амбра и ваниль постепенно превращают фруктовую сочность в нежный, обволакивающий шлейф.\n\nPoire Émeraude понравится тем, кто любит фруктовую гурманику с характером: аппетитную, сияющую, игривую, но не тяжёлую. Особенно тем, кто ищет аромат с красивой, запоминающейся грушей.","notes":{"top":"бергамот, вишня, груша наши.","middle":"миндаль, карамель; в некоторых торговых описаниях также указан жасмин.","base":"амбра, бурбонская ваниль.","other":""},"brand":"AMEHA Paris","name":"Poire Émeraude","price3":1200,"price5":2000,"price10":4000,"priceFull":null,"available":true,"hit":false,"new":true,"image":"assets/products/100.webp","placeholder":false},{"id":101,"title":"Guerlain — L’Homme Idéal (версия Eau de Parfum — требует подтверждения)","tagline":"Миндальный · ванильный · кожаный","description":"L’Homme Idéal — аромат мужчины, которого не нужно идеализировать. Гораздо интереснее, когда за хорошими манерами обнаруживаются чувство юмора, уверенность и немного озорства.\n\nПредставьте поздний ужин в небольшом ресторане. Тёмный пиджак, тёплый свет, бокал амаретто и разговор, который становится всё интереснее. В этой атмосфере нет показной серьёзности — только зрелая привлекательность и умение наслаждаться моментом.\n\nМиндаль здесь бархатистый, чуть ликёрный, с характерной горчинкой. Тёплая ванильная настойка смягчает его, а кожаный аккорд придаёт композиции собранность и глубину. Получается выразительный контраст: гурманская нежность и уверенная мужская элегантность.\n\nЭтот аромат понравится тем, кто любит тёплые, притягательные, слегка сладкие мужские композиции, где миндаль звучит не как десерт, а как часть дорогого вечернего образа.","notes":{"top":"Миндаль, пряности, лаванда, бергамот, розмарин, тимьян.","middle":"Вишня, ваниль, ладан, болгарская роза.","base":"Бобы тонка, кожаный аккорд, сандал.","other":"миндаль, ванильная настойка, кожа."},"brand":"Guerlain","name":"L’Homme Idéal (версия — требует подтверждения) EDP","price3":450,"price5":750,"price10":1500,"priceFull":null,"available":true,"hit":false,"new":false,"image":"assets/products/101.webp","placeholder":false,"photo_reference_source":"https://www.guerlain.com/dw/image/v2/BDCZ_PRD/on/demandware.static/-/Sites-GSA_master_catalog/default/dwd551e7e1/primary_packshot_3/2023/Fragrances/MASCULINS/L_HOMME_IDEAL_EDP_100ml-226597.png?sh=900&sw=900"},{"id":102,"title":"Kilian — Angels’ Share Eau de Parfum","tagline":"Коньячный · пряный · древесно-гурманский","description":"Angels’ Share — аромат вечера, когда хочется забыть о времени и позволить себе немного больше удовольствия, чем обычно.\n\nПредставьте старинный особняк. В камине потрескивают дрова, на столе стоит хрустальный бокал коньяка, рядом — яблочный пирог с корицей. За окнами холодно, а внутри тепло, спокойно и так красиво, что хочется остаться до утра.\n\nКоньячный аккорд создаёт насыщенное, почти ликёрное начало. Корица добавляет согревающую пряность, дубовая древесина напоминает о бочках, в которых выдерживают благородные напитки. Бобы тонка, сандал, пралине и ваниль придают композиции бархатистую сладость и мягкую глубину.\n\nAngels’ Share понравится тем, кто любит густые, роскошные, уютные ароматы с характером. Он напоминает не просто десерт, а целый вечер, в котором есть вкус, тепло, близость и ощущение красивой жизни.","notes":{"top":"Коньяк.","middle":"Дуб, корица.","base":"Бобы тонка, сандал, ваниль, пралине.","other":"коньяк, дуб, корица, бобы тонка, сандал, пралине, ваниль."},"brand":"Kilian","name":"Angels’ Share EDP","price3":1500,"price5":2500,"price10":5000,"priceFull":null,"available":true,"hit":true,"new":false,"image":"assets/products/102.webp","placeholder":false},{"id":103,"title":"Ormonde Jayne — Verano Eau de Parfum","tagline":"Цитрусовый · древесный · табачный · замшевый","description":"Verano — аромат человека, который умеет жить с размахом, но ценит не показную роскошь, а свободу выбирать собственный маршрут.\n\nПредставьте Латинскую Америку в разгар лета. Белые стены старого отеля, горячий камень под ногами, терпкий грейпфрут со льдом и кожаная дорожная сумка, уже готовая к следующему путешествию. Воздух наполнен солнцем, а впереди — день, в котором всё может случиться.\n\nВ начале Verano — сочный, искристый и чуть горьковатый: грейпфрут и бергамот встречаются с апельсином, прохладным можжевельником и пряным кардамоном. Затем цитрусовая яркость смягчается цветами магнолии, розы, фиалки и прозрачными чайными оттенками.\n\nНо особенный характер появляется в шлейфе. Табачный лист, мягкая замша и сандал придают композиции сухую, благородную теплоту, а кашмеран добавляет сливочную, почти бархатную фактуру. Представьте тонкую кожу, согретую солнцем, и дорогую рубашку, в которую впитался аромат дальних дорог.\n\nVerano понравится тем, кто любит свежие ароматы с неожиданной глубиной: энергичные цитрусы, благородную древесность, элегантную замшу и тонкий табачный оттенок. Он красив и на мужчине, и на женщине — особенно если в характере есть независимость и любовь к приключениям.","notes":{"top":"грейпфрут, бергамот, воздушный аккорд, абсолют апельсина, можжевельник, мускатный шалфей, кардамон.","middle":"магнолия, роза, фиалка, чайные ноты.","base":"кашмеран, табачный лист, Iso E Super, замша, сандал, мох, бобы тонка, серая амбра.","other":""},"brand":"Ormonde Jayne","name":"Verano EDP","price3":900,"price5":1500,"price10":3000,"priceFull":null,"available":true,"hit":false,"new":true,"image":"assets/products/103.webp","placeholder":false},{"id":104,"brand":"Valentino","name":"Anatomy of Dreams Private Talk","title":"Valentino — Anatomy of Dreams Private Talk","tagline":"Тубероза · имбирь · кофе","description":"Контрастный и уютный Private Talk строится на встрече яркого имбиря с насыщенными белыми цветами. Тубероза раскрывается бархатисто, а кофейный аккорд добавляет композиции тепла и глубины.\n\nВ основе остаются сандал, древесные оттенки и мягкий мускус. Аромат для настроения, в котором есть и смелость, и желание остаться наедине с собой.","notes":{"top":"Эссенция имбиря, экстракт имбиря SFE","middle":"Абсолют туберозы из Индии, иланг-иланг, аккорд капучино","base":"Сандал из Новой Каледонии, виргинский кедр, белый мускус","other":""},"price3":null,"price5":null,"price10":null,"priceFull":null,"available":true,"hit":false,"new":true,"image":"assets/products/104.webp","placeholder":false,"source":"manufacturer_and_retailer_research","noteSource":"https://www.valentino-beauty.us/anatomy-of-dreams/private-talk-parfum-MPL02356.html","noteSourceNote":"Официальная пирамида Valentino: указаны два разных экстракта имбиря в верхних нотах."},{"id":105,"brand":"Guerlain","name":"Néroli Outrenoir EDP","title":"Guerlain — Néroli Outrenoir Eau de Parfum","tagline":"Чёрный чай · нероли · цитрусы","description":"Néroli Outrenoir соединяет сияющую цитрусовую свежесть с выразительным, слегка дымным звучанием чёрного чая. Цветок апельсина и нероли смягчают контраст, придавая ему прозрачную элегантность.\n\nПозже появляются бархатистые смолы, дубовый мох и спокойное тепло ванили. Небанальный аромат, в котором светлая свежесть обретает глубокое послевкусие.","notes":{"top":"Петитгрейн, бергамот, танжерин, лимон, грейпфрут.","middle":"Чай, нероли, цветок апельсина, дымные и землистые аккорды.","base":"Ваниль, дубовый мох, мирра, бензоин, амбретта.","other":"Бергамот, петитгрейн, нероли, дымный чай"},"price3":null,"price5":null,"price10":null,"priceFull":null,"available":true,"hit":false,"new":true,"image":"assets/products/105.webp","placeholder":false,"source":"manufacturer_and_retailer_research","photo_reference_source":"https://lukesscents.com/cdn/shop/files/Image158.jpg?v=1745667338","noteSource":"https://www.guerlain.com/us/en-us/p/l%E2%80%99art-la-matiere-neroli-outrenoir-eau-de-parfum-P017910.html","noteSourceNote":"Guerlain подтверждает четыре ключевые ноты, но не публикует строгую трёхуровневую пирамиду. Основные ноты приведены вместе."},{"id":106,"brand":"Amouage","name":"Line 618 Essence de Parfum","title":"Amouage — Line 618 Essence de Parfum","tagline":"Молочные ноты · ладан · древесина","description":"Line 618 раскрывается необычным сочетанием фруктовой сочности, прохладного ладана и мягкой молочной текстуры. Контраст между перцем и нежными оттенками персика создаёт современное, многослойное впечатление.\n\nВ сердце появляются гелиотроп, кокосовое молоко и зелёная хвойность. Древесно-кожаная база делает аромат спокойнее, плотнее и глубже.","notes":{"top":"Оманский ладан Hojari, чёрный перец, ананас, персик, слива","middle":"Сосна, гелиотроп, кокосовое молоко","base":"Пачули, сандал, гваяковое дерево, кожа","other":""},"price3":null,"price5":null,"price10":null,"priceFull":null,"available":true,"hit":false,"new":true,"image":"assets/products/106.webp","placeholder":false,"source":"manufacturer_and_retailer_research","photo_reference_source":"https://www.ingredients-store.com/data/images/a8/line-cr_sq_retina.1000x1600.shrink_only.q85.jpg","noteSource":"https://amouage.com/en-eu/products/line-618","noteSourceNote":"Точная официальная пирамида Amouage."},{"id":107,"brand":"Clive Christian","name":"Strange Heavens Out of the Blue","title":"Clive Christian — Strange Heavens Out of the Blue","tagline":"Кофе · анис · какао","description":"Strange Heavens Out of the Blue играет на сочетании кофейной горчинки, пряного аниса и нежных белых цветов. Его настроение неожиданное: одновременно мягкое, насыщенное и чуть загадочное.\n\nКакао, ваниль и оттенки карамели формируют тёплое гурманское послевкусие. Подойдёт тем, кто любит выразительные композиции с необычным поворотом.","notes":{"top":"Кофе, анис","middle":"Жасмин, цветок апельсина, фирменный аккорд Addictive Fusion","base":"Абсолют какао, ванильная карамель, дымный аккорд","other":""},"price3":null,"price5":null,"price10":null,"priceFull":null,"available":true,"hit":false,"new":true,"image":"assets/products/107.webp","placeholder":false,"source":"manufacturer_and_retailer_research","noteSource":"https://www.clivechristian.com/products/strange-heavens-out-of-the-blue","noteSourceNote":"Clive Christian перечисляет эти материалы в официальном описании."},{"id":108,"brand":"Byredo","name":"Bal d’Afrique EDP","title":"Byredo — Bal d’Afrique Eau de Parfum","tagline":"Бергамот · фиалка · ветивер","description":"Bal d’Afrique - светлая, живая композиция, где цитрусовая свежесть встречается с мягкими цветами и тёплым древесным фоном. Бергамот и чёрная смородина дают энергичное начало, а фиалка и цикламен добавляют элегантную пудровость.\n\nКедр, ветивер, мускус и бобы тонка остаются в шлейфе тонким, хорошо сбалансированным аккордом. Аромат лёгкого движения, тепла и свободы.","notes":{"top":"Бучу, африканские бархатцы, бергамот, чёрная смородина","middle":"Цикламен, лепестки жасмина, фиалка","base":"Абсолют бобов тонка, кедр, мускус, ветивер","other":""},"price3":null,"price5":null,"price10":null,"priceFull":null,"available":true,"hit":false,"new":true,"image":"assets/products/108.webp","placeholder":false,"source":"manufacturer_and_retailer_research","photo_reference_source":"https://www.sephora.com/productimages/sku/s2924538-main-zoom.jpg","noteSource":"https://www.byredo.com/eu_en/p/bal-d-afrique-eau-de-parfum?sku=0065212491","noteSourceNote":"Точная официальная пирамида Byredo."},{"id":109,"brand":"Richard Maison de Parfum","name":"White Chocola EDP","title":"Richard Maison de Parfum — White Chocola Eau de Parfum","tagline":"Белый шоколад · миндаль · ваниль","description":"White Chocola посвящён нежной, сливочной сладости, в которой слышны белый шоколад, миндаль и ваниль. Мандарин и пряный мускатный орех освежают начало, не давая ему стать слишком тяжёлым.\n\nПудровые цветочные оттенки раскрываются постепенно, оставляя мягкий уютный шлейф. Это гурманское настроение без резкости, словно любимый десерт в красивой кондитерской.","notes":{"top":"Мандарин, мускатный орех, цветок персика","middle":"Белый шоколад, ваниль, миндаль","base":"Цветок миндаля, мимоза, ваниль, белый шоколад, цветок черешни","other":""},"price3":null,"price5":null,"price10":null,"priceFull":null,"available":true,"hit":false,"new":true,"image":"assets/products/109.webp","placeholder":false,"source":"manufacturer_and_retailer_research","photo_reference_source":"https://fragrancerevolutionboutique.co.uk/cdn/shop/files/01RICHARDMAISONDEPARFUMWhiteChocolaEaudeParfum.webp?v=1753468089&width=1946","noteSource":"https://richardperfume.com/product/white-chocola/","noteSourceNote":"Официальная трёхступенчатая пирамида RICHARD White Chocola Eau de Parfum; не путать с White Chocola Extrait."},{"id":110,"brand":"Creed","name":"Absolu Aventus EDP","title":"Creed — Absolu Aventus Eau de Parfum","tagline":"Грейпфрут · ананас · ветивер","description":"Absolu Aventus переосмысливает узнаваемый фруктово-древесный характер Aventus. Искристый грейпфрут и имбирь создают бодрое первое впечатление, за которым появляется яркий ананас с тёплыми пряностями.\n\nСмолистый лабданум, ветивер и пачули формируют выразительный, стойкий по характеру древесный финал. Собранный, динамичный и заметный аромат.","notes":{"top":"Калабрийский бергамот, грейпфрут, лимон","middle":"Ананас, кардамон, корица, имбирь","base":"Лабданум, пачули, гаитянский ветивер","other":""},"price3":null,"price5":null,"price10":null,"priceFull":null,"available":true,"hit":false,"new":true,"image":"assets/products/110.webp","placeholder":false,"source":"manufacturer_and_retailer_research","photo_reference_source":"https://www.creedperfume.com.au/cdn/shop/files/AbsoluAventus50ml.png?v=1749012260","noteSource":"https://www.creedfragrance.com/p/absolu-aventus/14926231/","noteSourceNote":"Ароматические материалы подтверждены описанием Creed. Разделение уровней основано на последовательности композиции, описанной брендом."},{"id":111,"brand":"Stefano Ricci","name":"Royal Eagle Sport EDP","title":"Stefano Ricci — Royal Eagle Sport Eau de Parfum","tagline":"Грейпфрут · зелёный чай · сандал","description":"Royal Eagle Sport открывается чистым и энергичным цитрусовым сочетанием мандарина с грейпфрутом. Затем композиция становится более зелёной: базилик, чай и жасмин добавляют свежести и аккуратной элегантности.\n\nСандал и белый мускус оставляют ровный, спокойный древесный шлейф. Хороший образ лёгкой спортивной собранности без излишней резкости.","notes":{"top":"Грейпфрут, мандарин","middle":"Базилик, зелёный чай, жасмин","base":"Сандал, белый мускус","other":""},"price3":null,"price5":null,"price10":null,"priceFull":null,"available":true,"hit":false,"new":true,"image":"assets/products/111.webp","placeholder":false,"source":"manufacturer_and_retailer_research","photo_reference_source":"https://dam-be.srspa.it/dam-images/onpremise/ecommerce_large/PM100RESP_-_001_01.jpg","noteSource":"https://www.stefanoricci.com/en-de/eau-de-parfum-royal-eagle-sport-50-ml/PM050RESP--.html","noteSourceNote":"Точная официальная пирамида Stefano Ricci."},{"id":112,"brand":"Parfums de Marly","name":"Layton Exclusif Parfum","title":"Parfums de Marly — Layton Exclusif Parfum","tagline":"Кардамон · лаванда · уд","description":"Layton Exclusif звучит глубже и темнее классического Layton. Свежие пряности и бергамот постепенно уступают место лавандовому сердцу, где строгая элегантность соседствует с мягкой цветочностью.\n\nВ базе раскрываются древесные, кожаные и удовые оттенки. Композиция плотная, характерная, созданная для тех, кто любит выразительное присутствие аромата.","notes":{"top":"Бергамот, грейпфрут, яблоко","middle":"Герань, корица, лаванда, агаровое дерево","base":"Циприол, гваяковое дерево, пачули, ваниль","other":""},"price3":null,"price5":null,"price10":null,"priceFull":null,"available":true,"hit":false,"new":true,"image":"assets/products/112.webp","placeholder":false,"source":"manufacturer_and_retailer_research","photo_reference_source":"https://us.parfums-de-marly.com/cdn/shop/files/LAYTON-EXCLUSIF-PERFUME-125-PACK11X1.png?v=1743177019&width=1445","noteSource":"https://us.parfums-de-marly.com/pages/the-exclusifs","noteSourceNote":"Официальная пирамида Parfums de Marly для Layton Exclusif; старые ноты обновлены."},{"id":113,"brand":"French Avenue","name":"Marmara Extrait de Parfum","title":"French Avenue — Marmara Extrait de Parfum","tagline":"Бергамот · кашмеран · сандал","description":"Marmara объединяет пряную искру чёрного перца и шафрана с ярким бергамотом. Постепенно свежесть смягчается пудровыми и кашемировыми оттенками, делая аромат более обволакивающим.\n\nМускусно-сандаловая база остаётся чистой, тёплой и элегантной. Это современная композиция со спокойным, благородным характером.","notes":{"top":"Чёрный перец, итальянский бергамот, шафран","middle":"Кашмировое дерево, амброксан, пудровый аккорд","base":"Мускус, белый сандал","other":""},"price3":null,"price5":null,"price10":null,"priceFull":null,"available":true,"hit":false,"new":true,"image":"assets/products/113.webp","placeholder":false,"source":"manufacturer_and_retailer_research","photo_reference_source":"https://frenchavenue.com/cdn/shop/files/3_36.jpg?v=1767962910&width=1206","noteSource":"https://sa.frenchavenue.com/products/marmara","noteSourceNote":"Ноты - официальный French Avenue KSA; концентрация там названа EDP, а в присланном каталоге Extrait. До уточнения версии концентрацию не меняем."},{"id":114,"brand":"Rosendo Mateu","name":"No. 5 Floral Amber Sensual Musk EDP","title":"Rosendo Mateu — No. 5 Floral Amber Sensual Musk Eau de Parfum","tagline":"Ландыш · гвоздика · амбра","description":"Rosendo Mateu No. 5 - бархатистая композиция, где белые цветы сочетаются с тёплыми специями. Ландыш звучит прозрачно, а гвоздика и шафран придают аромату характерную пряную глубину.\n\nАмбра, ваниль, мускус и бобы тонка создают густой, нежный шлейф. В нём чувствуются тепло, объём и особенная чувственность.","notes":{"top":"Ландыш, шафран","middle":"Гвоздика, ландыш","base":"Ваниль, амбра, белый мускус, бобы тонка, клубничный акцент","other":""},"price3":null,"price5":null,"price10":null,"priceFull":null,"available":true,"hit":false,"new":true,"image":"assets/products/114.webp","placeholder":false,"source":"manufacturer_and_retailer_research","photo_reference_source":"https://cdn2.parfumdreams.de/image/product/96919-0-0-2.webp","noteSourceNote":"Пирамида уточнена по официальному описанию Rosendo Mateu; в сердце повторно упоминается ландыш.","noteSource":"https://rosendomateu.com/producto/rosendo-mateu-5/"},{"id":115,"brand":"Ormonde Jayne","name":"Levant EDP","title":"Ormonde Jayne — Levant Eau de Parfum","tagline":"Цитрусы · пион · мускус","description":"Levant вдохновлён ощущением утреннего света и мягкого воздуха. Цитрусы раскрываются рядом с лепестками розы, затем переходят в утончённое сердце из пиона, ландыша, жасмина и флердоранжа.\n\nМускус, кедр и амбра создают спокойную базу без тяжести. Аромат элегантной чистоты и воздушных цветов.","notes":{"top":"Бергамот, мандарин, танжело, лепестки розы","middle":"Ландыш, пион, цветок апельсина, жасмин","base":"Кедр, амбра, мускус","other":""},"price3":null,"price5":null,"price10":null,"priceFull":null,"available":true,"hit":false,"new":true,"image":"assets/products/115.webp","placeholder":false,"source":"manufacturer_and_retailer_research","photo_reference_source":"https://cremedelacreme.shop/cache/galleries/142-26267/ormonde-jayne-levant-edp-1-kvapusis-vanduo-edp-88-creme-de-la-creme.jpeg","noteSource":"https://ormondejayne.com/en-de/products/levant","noteSourceNote":"Точная официальная пирамида Ormonde Jayne."},{"id":116,"brand":"Ormonde Jayne","name":"Champaca EDP","title":"Ormonde Jayne — Champaca Eau de Parfum","tagline":"Чампака · зелёный чай · басмати","description":"Champaca - утончённая и необычная цветочная композиция. Нероли и бамбук придают ей прохладное начало, а чампака и фрезия раскрываются на мягком, чуть рисовом фоне.\n\nЗелёный чай, мирра и мускус создают деликатную, медитативную глубину. Это аромат камерного уюта и спокойной красоты.","notes":{"top":"Нероли, розовый перец, бамбук","middle":"Абсолют чампаки, абсолют фрезии, рис басмати","base":"Мирра, зелёный чай, мускус","other":""},"price3":null,"price5":null,"price10":null,"priceFull":null,"available":true,"hit":false,"new":true,"image":"assets/products/116.webp","placeholder":false,"source":"manufacturer_and_retailer_research","photo_reference_source":"https://losaromas.ee/image/catalog/products/ORMONDE%20JAYNE/Ormonde%20Jayne%20Champaca%20EDP.jpg","noteSource":"https://ormondejayne.com/en-de/products/champaca-1","noteSourceNote":"Точная официальная пирамида Ormonde Jayne."},{"id":117,"brand":"Escentric Molecules","name":"Molecule 01 + Clary Sage Eau de Toilette","title":"Escentric Molecules — Molecule 01 + Clary Sage Eau de Toilette","tagline":"Iso E Super · мускатный шалфей","description":"Molecule 01 + Clary Sage строится вокруг взаимодействия двух основных компонентов: прозрачного древесного Iso E Super и травянистого мускатного шалфея. В этом сочетании есть прохлада, природная свежесть и едва заметная бархатистость.\n\nБренд описывает дуэт компонентов, а не классическую трёхступенчатую пирамиду, поэтому на сайте указаны основные ноты без придуманного деления на верх, сердце и базу.","notes":{"top":"Мускатный шалфей (свежий травяной аккорд).","middle":"Мускатный шалфей и Iso E Super (две заявленные ноты).","base":"Iso E Super (мягкий древесный шлейф, без дополнительных нот).","other":"Iso E Super, мускатный шалфей"},"price3":null,"price5":null,"price10":null,"priceFull":null,"available":true,"hit":false,"new":true,"image":"assets/products/117.webp","placeholder":false,"source":"manufacturer_and_retailer_research","photo_reference_source":"https://karjistore.com/cdn/shop/files/escentric-molecules-molecule-01-clary-sage-edt-100ml-01.jpg?v=1788937087&width=2000","noteSource":"https://www.escentric.com/en-us/products/molecule-01-clary-sage","noteSourceNote":"У производителя ровно два основных компонента, отдельную пирамиду не заявляют: не добавляем вымышленные ингредиенты."},{"id":118,"brand":"HFC","name":"Devil’s Intrigue EDP","title":"HFC — Devil’s Intrigue Eau de Parfum","tagline":"Белый чай · османтус · кашмирское дерево","description":"Devil’s Intrigue раскрывается мягко и интригующе: османтус и белый чай создают тонкое, слегка абрикосовое настроение. В сердце цветок апельсина встречается с нежным сандалом.\n\nКашмирские древесные оттенки, рисовое молоко, амбровое тепло и ваниль формируют приятную кремовую глубину. Композиция одновременно нежная и выразительная.","notes":{"top":"Османтус, белый чай","middle":"Апельсиновый цвет, сандал","base":"Кашемировое дерево, амбровое дерево, рисовое молоко, ваниль","other":""},"price3":null,"price5":null,"price10":null,"priceFull":null,"available":true,"hit":false,"new":true,"image":"assets/products/118.webp","placeholder":false,"source":"manufacturer_and_retailer_research","noteSourceNote":"Официальная пирамида HFC Devil’s Intrigue.","noteSource":"https://www.hfcparis.com/catalog/devils-intrigue"},{"id":119,"brand":"Initio","name":"Narcotic Delight EDP","title":"Initio — Narcotic Delight Eau de Parfum","tagline":"Вишня · коньяк · табак","description":"Narcotic Delight построен на дерзком контрасте сочной вишни, тёплого коньяка, ванили и пряного перца. Табак добавляет композиции суховатую дымную глубину, а хедион делает звучание более воздушным.\n\nПроизводитель публикует основные ноты без распределения по классическим ступеням, поэтому я оставляю их в разделе аккордов без искусственного распределения.","notes":{"top":"Вишня, розовый перец, чёрный перец.","middle":"Коньяк, гедион, роза.","base":"Табак, ваниль, бобы тонка, кедр, пачули.","other":"Вишня, коньяк, ваниль, чёрный перец, розовый перец, табак, гедион"},"price3":null,"price5":null,"price10":null,"priceFull":null,"available":true,"hit":false,"new":true,"image":"assets/products/119.webp","placeholder":false,"source":"manufacturer_and_retailer_research","photo_reference_source":"https://static.wixstatic.com/media/e53f7d_1aebcc9cf6a842f296280acd951c04b2~mv2.jpg/v1/fit/w_500%2Ch_500%2Cq_90/file.jpg","noteSource":"https://initioparfums.com/products/narcotic-delight","noteSourceNote":"INITIO официально указывает 7 основных нот БЕЗ разбивки верх/сердце/база. Сохраняем список без выдуманного деления."},{"id":120,"brand":"Hermès","name":"Terre d’Hermès Parfum","title":"Hermès — Terre d’Hermès Parfum","tagline":"Грейпфрут · шисо · кедр","description":"Terre d’Hermès Parfum передаёт ощущение земли, дерева и минеральной свежести. В аромате сочетаются яркий грейпфрут, необычная зелёная нота шисо и обволакивающий кедр.\n\nЭто именно версия Parfum, а не Eau de Parfum Intense. Дом Hermès выделяет ключевые материалы, не представляя их как трёхступенчатую пирамиду, поэтому здесь сохранены официальные ноты.","notes":{"top":"Апельсин, грейпфрут, шисо.","middle":"Кремень (минеральный аккорд).","base":"Древесные ноты, кедр, дубовый мох, бензоин.","other":"Грейпфрут, кедр, шисо"},"price3":null,"price5":null,"price10":null,"priceFull":null,"available":true,"hit":false,"new":true,"image":"assets/products/120.webp","placeholder":false,"source":"manufacturer_and_retailer_research","photo_reference_source":"https://poelmanparfums.nl/5996-medium_default/hermes-terre-dhermes-pure-perfum.jpg","noteSource":"https://www.hermes.com/us/en/product/terre-d-hermes-parfum-V107758V0/","noteSourceNote":"Hermès подтверждает 3 основных материала, уровней пирамиды не публикует."},{"id":121,"brand":"Clive Christian","name":"Addictive Arts Jump Up and Kiss Me Hedonistic Parfum","title":"Clive Christian — Addictive Arts Jump Up and Kiss Me Hedonistic Parfum","tagline":"Чай мате · табак · лабданум","description":"Hedonistic сочетает пряно-травянистые оттенки чая мате с сочными фруктами и яркими цитрусами. Сердце раскрывает тёплый табак в окружении жасмина и пудрового ириса.\n\nЛабданум, кожа и амбра делают финал более глубоким и смолистым, а ваниль и бобы тонка добавляют мягкости. Богатая, насыщенная композиция с вечерним характером.","notes":{"top":"Чай мате, бергамот, грейпфрут, нероли, чёрная вишня, мускатный шалфей","middle":"Табак, жасмин, ирис, папирус","base":"Лабданум, кожа, амбра, бобы тонка, ваниль","other":""},"price3":null,"price5":null,"price10":null,"priceFull":null,"available":true,"hit":false,"new":true,"image":"assets/products/121.webp","placeholder":false,"source":"manufacturer_and_retailer_research","photo_reference_source":"https://scentrabbit.com/cdn/shop/files/jump-up-kiss-me.png?v=1781218133&width=1920","noteSource":"https://www.clivechristian.com/products/jump-up-and-kiss-me-hedonistic","noteSourceNote":"По подробному описанию производителя, который выделяет основные ноты чай мате / табак / лабданум."},{"id":122,"brand":"Amouage","name":"Interlude Man EDP","title":"Amouage — Interlude Man Eau de Parfum","tagline":"Орегано · ладан · дымное дерево","description":"Interlude Man узнаётся по смелому пряному началу: орегано и пимент соединяются с бергамотом. Затем раскрывается насыщенное смолистое сердце, где ладан и опопонакс создают ощущение тепла и дыма.\n\nДревесная база с кожей, пачули и сандалом добавляет глубины. Это интенсивная композиция для любителей ярких, сложных восточных ароматов.","notes":{"top":"Бергамот, орегано, ягоды пимента","middle":"Амбра, ладан, цистус, опопонакс","base":"Кожа, дым агарового дерева, пачули, сандал","other":""},"price3":null,"price5":null,"price10":null,"priceFull":null,"available":true,"hit":false,"new":true,"image":"assets/products/122.webp","placeholder":false,"source":"manufacturer_and_retailer_research","photo_reference_source":"https://cdn.shopify.com/s/files/1/0594/0360/0065/products/amouage-interlude-eau-de-parfum-para-hombre___30_1000x1000.jpg?v=1632946145","noteSource":"https://amouage.com/en-uk/products/interlude-man-100ml","noteSourceNote":"Точная официальная пирамида Amouage."},{"id":123,"brand":"Chopard","name":"Tubéreuse Maharané EDP","title":"Chopard — Tubéreuse Maharané Eau de Parfum","tagline":"Тубероза · белый шоколад · сандал","description":"Tubéreuse Maharané превращает туберозу в насыщенное цветочное сердце, окружённое неожиданным аккордом белого шоколада. Сливочная сладость мягко оттеняет выразительную белоцветочную ноту.\n\nСандал в базе добавляет композиции тепла и спокойной древесной элегантности. Получается гурманский и одновременно цветочный аромат.","notes":{"top":"Белый шоколад","middle":"Тубероза (индийский абсолют)","base":"Сандал","other":""},"price3":null,"price5":null,"price10":null,"priceFull":null,"available":true,"hit":false,"new":true,"image":"assets/products/123.webp","placeholder":false,"source":"manufacturer_and_retailer_research","photo_reference_source":"https://douglas.bg/media/catalog/product/cache/01e1c0038a30504fa3f60f9f4d2db92d/1/-/1-f581a072e2710bfe7388b35b1c2ac5bb.jpg","noteSource":"https://www.chopard.com/en-intl/haute-parfumerie/95201-0462.html","noteSourceNote":"Производитель подтверждает ПО ОДНОЙ ноте на ступень. Их нельзя искусственно увеличить до трёх."},{"id":124,"brand":"Les Liquides Imaginaires","name":"Blanche Bête EDP","title":"Les Liquides Imaginaires — Blanche Bête Eau de Parfum","tagline":"Молочный аккорд · тубероза · мускус","description":"Blanche Bête обволакивает нежным молочным аккордом, к которому постепенно присоединяются тубероза, жасмин и мягкие дымно-смолистые оттенки ладана. Сердце композиции звучит воздушно и бархатисто.\n\nТонка, какао и мускусная ваниль создают деликатный, тёплый шлейф. Это мечтательный, уютный аромат с заметной индивидуальностью.","notes":{"top":"Семена амбретты, молочный аккорд, Mystikal","middle":"Жасмин, лепестки туберозы, Mahonial, ладан","base":"Бобы тонка, какао, мускусная ваниль","other":""},"price3":null,"price5":null,"price10":null,"priceFull":null,"available":true,"hit":false,"new":true,"image":"assets/products/124.webp","placeholder":false,"source":"manufacturer_and_retailer_research","photo_reference_source":"https://www.eleganteprofumi.com/cdn/shop/files/BLANCHE2_5_11zon.webp?v=1754405200&width=1200","noteSourceNote":"Официальная пирамида Les Liquides Imaginaires Blanche Bête.","noteSource":"https://eu.liquidesimaginaires.com/products/blanche-bete"}];
